        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        dropoffNotes,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: deliveryPrice, distance: 3, operatorId: 'main', zoneId: 'monofia',
        paymentMethod: 'CASH', restaurantName: manualRestName, pickupNotes: `طلب يدوي: ${manualMeal}`
      };
      await addDoc(collection(db, "orders"), orderData);

      const waMsg = `🍳 *طلب طعام (مطعم غير موجود)*\n🏪 *المطعم:* ${manualRestName}\n🍲 *الوجبة:* ${manualMeal}\n📍 *التوصيل:* ${dropoffVillage.name}\n👤 *العميل:* ${user.name}\n📱 *الهاتف:* ${user.phone}`;
      window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent(waMsg)}`, '_blank');

      setShowManualFood(false);
      setManualRestName('');
      setManualMeal('');
    } catch (e) { alert('خطأ في إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  const handleCreatePharmacyOrder = async () => {
    if (!dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    if (!pharmacyNotes.trim() && !prescriptionImage) return alert('يرجى كتابة أسماء الأدوية أو إرفاق صورة الروشتة');

    setIsSubmitting(true);
    setIncomingOffers([]);
    try {
      const dist = 3; 
      const deliveryPrice = DEFAULT_PRICING.minPrice;

