                           <h3 className="text-4xl font-black">
                              {isCalculatingAiDist ? <Loader2 className="animate-spin inline-block h-8 w-8" /> : approxRidePrice} 
                              {!isCalculatingAiDist && <span className="text-xs opacity-40 font-bold uppercase ml-2">ج.م</span>}
