                   <div className="text-right">
                      <h3 className="text-2xl font-black text-slate-900">مراكز المنوفية</h3>
                      <p className="text-[10px] font-bold text-slate-400 tracking-widest uppercase">اختر المركز لفلترة القرى</p>
