};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [ads, setAds] = useState<Ad[]>([]);
  const [pricingConfig, setPricingConfig] = useState(DEFAULT_PRICING);

  // States
  const [pickupDistrict, setPickupDistrict] = useState<District | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffDistrict, setDropoffDistrict] = useState<District | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [rideVehicleType, setRideVehicleType] = useState<VehicleType>('TOKTOK');
  const [aiRoadDistance, setAiRoadDistance] = useState<number | null>(null);
  const [isCalculatingAiDist, setIsCalculatingAiDist] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [showChat, setShowChat] = useState(false);

  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]));
    onSnapshot(collection(db, "ads"), (snap) => setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]));
    onSnapshot(doc(db, "settings", "pricing"), (snap) => { if(snap.exists()) setPricingConfig({...DEFAULT_PRICING, ...snap.data()}); });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  // AI Distance Logic
  useEffect(() => {
    const fetchAiDistance = async () => {
      if (!pickupVillage || !dropoffVillage) { setAiRoadDistance(null); return; }
      setIsCalculatingAiDist(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const straightDist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `قدر المسافة الحقيقية "طريق أسفلت" بين ${pickupVillage.name} و ${dropoffVillage.name} بالمنوفية. المسافة المباشرة ${straightDist} كم. أجب بالرقم فقط بالكم.`,
        });
        const dist = parseFloat(response.text?.trim() || '0');
        setAiRoadDistance(!isNaN(dist) && dist > 0 ? dist : straightDist * 1.3);
      } catch (e) { setAiRoadDistance(calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng) * 1.3); } 
      finally { setIsCalculatingAiDist(false); }
    };
    fetchAiDistance();
  }, [pickupVillage?.id, dropoffVillage?.id]);

  const calculatedPrice = useMemo(() => {
    if (!pickupVillage || !dropoffVillage) return 0;
    const dist = aiRoadDistance || calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
    const multiplier = pricingConfig.multipliers[rideVehicleType] || 1;

    // حساب الخدمات (طعام وصيدلية)
    if (selectedCategory === 'FOOD' || selectedCategory === 'PHARMACY') {
       if (pickupVillage.id === dropoffVillage.id) return pricingConfig.serviceSameVillagePrice;
       return Math.max(Math.round(dist * pricingConfig.servicePricePerKm), pricingConfig.serviceSameVillagePrice);
    }

    // حساب المشاوير (TAXI)
    if (pickupVillage.id === dropoffVillage.id) return pricingConfig.rideSameVillagePrice;
    return Math.max(Math.round((pricingConfig.rideBasePrice + (dist * pricingConfig.ridePricePerKm)) * multiplier), pricingConfig.rideMinPrice);
  }, [pickupVillage, dropoffVillage, selectedCategory, rideVehicleType, aiRoadDistance, pricingConfig]);

  const handleCreateOrder = async () => {
    if(!pickupVillage || !dropoffVillage) return;
    setIsSubmitting(true);
    try {
       await addDoc(collection(db, "orders"), {
          customerId: user.id, customerPhone: user.phone, category: selectedCategory,
          pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
          dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
          pickupNotes, dropoffNotes, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(),
          requestedVehicleType: rideVehicleType, price: calculatedPrice, distance: aiRoadDistance || 0,
          operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
       });
       window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent(`طلب ${selectedCategory} من ${pickupVillage.name} إلى ${dropoffVillage.name} بسعر ${calculatedPrice}`)}`, '_blank');
    } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={false} onClose={() => {}} />
      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-slate-50">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-8 md:p-12 space-y-8 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div><h2 className="text-4xl font-black text-slate-950">وصـــلــهــا المنوفية</h2><p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-1">تغطية ذكية للمحافظة</p></div>
                 <button className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl active:scale-90 shadow-sm border-none"><Bot className="h-8 w-8" /></button>
              </div>

              <div className="grid grid-cols-3 gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'طعام', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'أدوية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                       {React.cloneElement(cat.icon as React.ReactElement, { className: "h-8 w-8" })}
                       <span className="text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              <div className="space-y-6">
                 <LocationSelector 
                    label={selectedCategory === 'TAXI' ? "نقطة الانطلاق" : "مكان الاستلام"} 
                    helper="من أين سنبدأ؟" icon={<MapPin />} iconBg="bg-emerald-500"
                    selectedDistrict={pickupDistrict} selectedVillage={pickupVillage} notes={pickupNotes}
                    onDistrictSelect={setPickupDistrict} onVillageSelect={setPickupVillage} onNotesChange={setPickupNotes}
                 />
                 <LocationSelector 
                    label="عنوان الوصول" helper="أين ستستلم طلبك؟" icon={<Check />} iconBg="bg-rose-500"
                    selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes}
                    onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes}
                 />
              </div>

              {selectedCategory === 'TAXI' && (
                <div className="grid grid-cols-3 gap-3">
                   {[{id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-5 w-5" />}, {id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-5 w-5" />}, {id: 'CAR', label: 'سيارة', icon: <Car className="h-5 w-5" />}].map(v => (
                     <button key={v.id} onClick={() => setRideVehicleType(v.id as VehicleType)} className={`py-6 rounded-[2rem] flex flex-col items-center gap-2 border-2 transition-all ${rideVehicleType === v.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl scale-105' : 'bg-white border-transparent text-slate-300'}`}>
                        {v.icon} <span className="text-[10px] font-black">{v.label}</span>
                     </button>
                   ))}
                </div>
              )}

              <div className="bg-slate-950 p-10 rounded-[3.5rem] text-white flex flex-col shadow-2xl relative overflow-hidden">
                 <div className="flex justify-between items-end mb-8 px-2">
                    <div className="text-right space-y-2">
                       <p className="text-[11px] font-black text-emerald-400 uppercase tracking-widest">التسعيرة الذكية (AI)</p>
                       <div className="flex items-center gap-6 flex-row-reverse justify-end">
                          <h3 className="text-5xl font-black">{isCalculatingAiDist ? <Loader2 className="animate-spin h-8 w-8" /> : calculatedPrice} <span className="text-sm opacity-40 font-bold uppercase mr-2">ج.م</span></h3>
                          <div className="h-10 w-px bg-white/10 mx-2"></div>
                          <div className="text-right">
                             <div className="flex items-center gap-2 text-emerald-300 flex-row-reverse"><Navigation2 className="h-4 w-4" /><span className="text-lg font-black">{isCalculatingAiDist ? '...' : (aiRoadDistance || 0)} <span className="text-[9px] opacity-60">كم</span></span></div>
                             <p className="text-[8px] font-bold text-slate-500 uppercase">طريق السير</p>
                          </div>
                       </div>
                    </div>
                 </div>
                 <button onClick={handleCreateOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-emerald-600 text-white py-6 rounded-[2.2rem] font-black text-xl shadow-2xl active:scale-95 transition-all z-10 hover:bg-emerald-500 disabled:opacity-50 border-none">
                    {isSubmitting ? <Loader2 className="animate-spin h-6 w-6 mx-auto" /> : 'اطلب الآن'}
                 </button>
              </div>
            </>
          ) : (
            <div className="animate-in zoom-in space-y-12 text-center">
               <div className="bg-white p-12 rounded-full shadow-2xl inline-block border-4 border-emerald-50"><Timer className="h-24 w-24 text-emerald-600 animate-pulse" /></div>
               <h2 className="text-3xl font-black text-slate-950">جاري استقبال عروض الكباتن...</h2>
               <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="w-full py-4 text-rose-500 font-black text-[10px] uppercase tracking-widest hover:bg-rose-50 rounded-2xl">إلغاء الطلب</button>
            </div>
          )}
        </div>
      </div>
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-10 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[{id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'}, {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'}, {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all border-none bg-transparent ${activeView === tab.id ? 'text-emerald-600 scale-125' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

