// --- مكون إدارة التسعيرة (Pricing Manager) ---
const PricingManager: React.FC = () => {
  const [pricing, setPricing] = useState(DEFAULT_PRICING);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    onSnapshot(doc(db, "settings", "pricing"), (snap) => {
      if (snap.exists()) setPricing({ ...DEFAULT_PRICING, ...snap.data() });
    });
  }, []);

  const handleSave = async () => {
    setLoading(true);
    try {
      await setDoc(doc(db, "settings", "pricing"), pricing);
      alert('تم حفظ التسعيرة بنجاح');
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  return (
    <div className="space-y-8 animate-reveal">
       <div className="bg-white p-8 rounded-[3.5rem] shadow-sm border border-slate-50 space-y-10">
          <div className="text-right">
             <h3 className="text-2xl font-black text-slate-900">إدارة التسعيرة</h3>
             <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">تعديل أسعار المشاوير والخدمات</p>
          </div>

          {/* تسعيرة المشاوير (Ride) */}
          <div className="space-y-6">
             <h4 className="font-black text-sm text-indigo-600 bg-indigo-50 px-4 py-2 rounded-xl inline-block">تسعيرة المشاوير (Ride/Taxi)</h4>
             <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-4 rounded-2xl">
                   <label className="text-[8px] font-black text-slate-400 block mb-1">فتح العداد (ج.م)</label>
                   <input type="number" value={pricing.basePrice} onChange={e => setPricing({...pricing, basePrice: Number(e.target.value)})} className="w-full bg-transparent font-black text-sm outline-none text-right" />
                </div>
                <div className="bg-slate-50 p-4 rounded-2xl">
                   <label className="text-[8px] font-black text-slate-400 block mb-1">سعر الكيلو (ج.م)</label>
                   <input type="number" value={pricing.pricePerKm} onChange={e => setPricing({...pricing, pricePerKm: Number(e.target.value)})} className="w-full bg-transparent font-black text-sm outline-none text-right" />
                </div>
                <div className="bg-slate-50 p-4 rounded-2xl">
                   <label className="text-[8px] font-black text-slate-400 block mb-1">الحد الأدنى (ج.م)</label>
                   <input type="number" value={pricing.minPrice} onChange={e => setPricing({...pricing, minPrice: Number(e.target.value)})} className="w-full bg-transparent font-black text-sm outline-none text-right" />
                </div>
                <div className="bg-slate-50 p-4 rounded-2xl">
                   <label className="text-[8px] font-black text-slate-400 block mb-1">داخل نفس القرية (ج.م)</label>
                   <input type="number" value={pricing.sameVillagePrice} onChange={e => setPricing({...pricing, sameVillagePrice: Number(e.target.value)})} className="w-full bg-transparent font-black text-sm outline-none text-right" />
                </div>
             </div>
          </div>

          {/* تسعيرة الخدمات (Service) */}
          <div className="space-y-6 pt-6 border-t border-slate-100">
             <h4 className="font-black text-sm text-emerald-600 bg-emerald-50 px-4 py-2 rounded-xl inline-block">تسعيرة الخدمات (طعام/صيدلية)</h4>
             <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-4 rounded-2xl">
                   <label className="text-[8px] font-black text-slate-400 block mb-1">داخل نفس القرية (ثابت 20 ج.م)</label>
                   <input type="number" value={pricing.serviceSameVillagePrice} onChange={e => setPricing({...pricing, serviceSameVillagePrice: Number(e.target.value)})} className="w-full bg-transparent font-black text-sm outline-none text-right" />
                </div>
                <div className="bg-slate-50 p-4 rounded-2xl">
                   <label className="text-[8px] font-black text-slate-400 block mb-1">سعر الكيلو خارج القرية (5 ج.م)</label>
                   <input type="number" value={pricing.servicePricePerKm} onChange={e => setPricing({...pricing, servicePricePerKm: Number(e.target.value)})} className="w-full bg-transparent font-black text-sm outline-none text-right" />
                </div>
             </div>
             <p className="text-[9px] font-bold text-slate-400 leading-relaxed">* في الخدمات لا يتم تفعيل "فتح العداد"؛ السعر يعتمد فقط على ما إذا كان الطلب في نفس القرية أو بالمسافة.</p>
          </div>

          <button onClick={handleSave} disabled={loading} className="w-full bg-slate-950 text-white py-6 rounded-[2.2rem] font-black text-lg shadow-2xl flex items-center justify-center gap-3">
