// --- مكون إدارة الإعلانات (Ad Manager) ---
const AdManager: React.FC = () => {
  const [ads, setAds] = useState<Ad[]>([]);
  const [loading, setLoading] = useState(false);
  const [isAdding, setIsAdding] = useState(false);
  const [newAd, setNewAd] = useState<Partial<Ad>>({
    title: '', description: '', type: 'general', isActive: true, imageUrl: ''
  });

  useEffect(() => {
    return onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });
  }, []);

  const handleSaveAd = async () => {
    if (!newAd.title || !newAd.imageUrl) return alert('أكمل بيانات الإعلان');
    setLoading(true);
    try {
      const adId = `ad_${Date.now()}`;
      await setDoc(doc(db, "ads", adId), {
        ...newAd,
        id: adId,
        createdAt: Date.now(),
        views: 0, clicks: 0, displayOrder: ads.length + 1
      });
      setIsAdding(false);
      setNewAd({ title: '', description: '', type: 'general', isActive: true, imageUrl: '' });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  return (
    <div className="space-y-6 animate-reveal">
      <div className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-sm space-y-8">
        <div className="flex justify-between items-center">
           <button onClick={() => setIsAdding(!isAdding)} className="bg-emerald-600 text-white px-6 py-3 rounded-2xl font-black text-xs flex items-center gap-2 shadow-lg active:scale-95 transition-all">
              {isAdding ? <X className="h-4 w-4" /> : <Plus className="h-4 w-4" />}
              {isAdding ? 'إلغاء' : 'إعلان جديد'}
           </button>
           <h3 className="text-xl font-black text-slate-800">إدارة الإعلانات</h3>
        </div>

        {isAdding && (
          <div className="bg-slate-50 p-8 rounded-[3rem] space-y-6 animate-in slide-in-from-top border-2 border-emerald-500/10">
             <div className="space-y-4">
                <input value={newAd.title} onChange={e => setNewAd({...newAd, title: e.target.value})} placeholder="عنوان الإعلان" className="w-full p-5 rounded-2xl font-black text-sm outline-none text-right shadow-inner bg-white" />
                <textarea value={newAd.description} onChange={e => setNewAd({...newAd, description: e.target.value})} placeholder="وصف الإعلان (اختياري)" className="w-full p-5 rounded-2xl font-bold text-sm outline-none text-right shadow-inner bg-white min-h-[100px]" />
                <input value={newAd.imageUrl} onChange={e => setNewAd({...newAd, imageUrl: e.target.value})} placeholder="رابط الصورة (URL)" className="w-full p-5 rounded-2xl font-bold text-xs outline-none text-left shadow-inner bg-white" dir="ltr" />
                <div className="grid grid-cols-2 gap-4">
                   <select value={newAd.type} onChange={e => setNewAd({...newAd, type: e.target.value as any})} className="p-5 rounded-2xl font-black text-xs outline-none text-right bg-white appearance-none">
                      <option value="general">عام</option>
                      <option value="restaurant">مطعم</option>
                      <option value="special_offer">عرض خاص</option>
                   </select>
                   <button onClick={handleSaveAd} disabled={loading} className="bg-slate-950 text-white rounded-2xl font-black text-sm">حفظ الإعلان</button>
                </div>
             </div>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
           {ads.map(ad => (
             <div key={ad.id} className="bg-slate-50 rounded-[2.5rem] overflow-hidden border border-slate-100 group relative">
                <div className="aspect-video relative overflow-hidden">
                   <img src={ad.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                   <div className="absolute inset-0 bg-gradient-to-t from-slate-950 p-6 flex flex-col justify-end">
                      <h4 className="text-white font-black">{ad.title}</h4>
                      <p className="text-[10px] text-slate-400 font-bold truncate">{ad.description}</p>
                   </div>
                </div>
                <div className="p-4 flex justify-between items-center bg-white">
                   <button onClick={async () => { if(confirm('حذف الإعلان؟')) await deleteDoc(doc(db, "ads", ad.id)); }} className="p-3 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 className="h-4 w-4" /></button>
                   <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{ad.type}</span>
                </div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

