              </div>
              <div className="bg-slate-900 p-10 rounded-[3.5rem] text-white shadow-xl">
                 <p className="text-[10px] font-black opacity-40 uppercase mb-1 tracking-widest">إجمالي الرحلات</p>
                 <h3 className="text-4xl font-black">{stats.orders}</h3>
