                            <span className={`px-4 py-1.5 rounded-xl text-[8px] font-black uppercase tracking-widest ${u.status === 'APPROVED' ? 'text-emerald-500 bg-emerald-50' : 'text-rose-500 bg-rose-50'}`}>{u.status}</span>
