                   </div>
                   <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                      <p className="text-xl font-black text-slate-900">{(u.wallet?.balance || 0).toFixed(1)} <span className="text-[9px] opacity-30">ج.م</span></p>
