const UserEditModal: React.FC<{ user: User, onClose: () => void }> = ({ user, onClose }) => {
  const [status, setStatus] = useState<UserStatus>(user.status);
  const [balance, setBalance] = useState(user.wallet?.balance || 0);
  const [loading, setLoading] = useState(false);

  const handleSave = async () => {
    setLoading(true);
    try {
      await updateDoc(doc(db, "users", user.id), {
        status,
        "wallet.balance": balance
      });
      alert('تم التحديث بنجاح');
      onClose();
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  return (
    <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-xl z-[12000] flex items-center justify-center p-4 animate-in fade-in">
      <div className="bg-white w-full max-w-md rounded-[3.5rem] p-10 space-y-8 shadow-2xl relative text-right">
        <div className="flex justify-between items-center px-2">
           <button onClick={onClose} className="p-3 bg-slate-50 text-slate-400 rounded-2xl hover:bg-slate-200 transition-all"><X className="h-5 w-5" /></button>
           <div>
              <h3 className="text-2xl font-black text-slate-900">تعديل حساب العضو</h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase">{user.name}</p>
           </div>
        </div>
        <div className="space-y-6">
           <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase px-4 block">حالة الحساب</label>
              <select value={status} onChange={e => setStatus(e.target.value as UserStatus)} className="w-full bg-slate-50 rounded-[1.5rem] p-5 font-black text-sm outline-none text-right appearance-none">
                 <option value="APPROVED">مفعّل ✅</option>
                 <option value="PENDING_APPROVAL">قيد الانتظار ⏳</option>
                 <option value="SUSPENDED">محظور 🚫</option>
              </select>
           </div>
           <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase px-4 block">الرصيد اليدوي (ج.م)</label>
              <input type="number" value={balance} onChange={e => setBalance(Number(e.target.value))} className="w-full bg-slate-50 rounded-[1.5rem] p-5 font-black text-xl outline-none text-right shadow-inner" />
           </div>
           <button onClick={handleSave} disabled={loading} className="w-full bg-slate-950 text-white py-6 rounded-[2rem] font-black shadow-xl flex items-center justify-center gap-3">
              {loading ? <Loader2 className="animate-spin h-6 w-6" /> : <><Save className="h-6 w-6 text-emerald-400" /> حفظ التغييرات</>}
           </button>
        </div>
      </div>
    </div>
  );
};

