              <p className="text-[10px] font-bold text-slate-400 uppercase truncate max-w-[200px]">{user.name}</p>
           </div>
        </div>

        <div className="space-y-6">
           <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase px-4 block">حالة الحساب</label>
