           <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase px-4 block">رصيد المحفظة (ج.م)</label>
              <div className="relative">
                <input type="number" value={balance} onChange={e => setBalance(Number(e.target.value))} className="w-full bg-slate-50 rounded-[1.5rem] p-5 pr-14 font-black text-xl outline-none shadow-inner focus:bg-white transition-all" />
                <DollarSign className="absolute right-5 top-1/2 -translate-y-1/2 h-5 w-5 text-emerald-500" />
              </div>
