           <button onClick={handleSave} disabled={loading} className="w-full bg-slate-950 text-white py-6 rounded-[2rem] font-black shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all">
              {loading ? <Loader2 className="animate-spin h-6 w-6" /> : <><Save className="h-6 w-6 text-emerald-400" /> حفظ التعديلات</>}
