// --- مكون إدارة الإعلانات ---
const AdManager: React.FC = () => {
  const [ads, setAds] = useState<Ad[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [newAd, setNewAd] = useState<Partial<Ad>>({ title: '', imageUrl: '', type: 'general', description: '' });

  useEffect(() => {
    return onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });
  }, []);

  const handleSave = async () => {
    if (!newAd.title || !newAd.imageUrl) return alert('أكمل البيانات');
    const id = `ad_${Date.now()}`;
    await setDoc(doc(db, "ads", id), { ...newAd, id, isActive: true, createdAt: Date.now(), displayOrder: ads.length });
    setIsAdding(false);
    setNewAd({ title: '', imageUrl: '', type: 'general', description: '' });
  };

  return (
    <div className="space-y-8 animate-reveal">
      <div className="bg-white p-10 rounded-[4rem] shadow-sm border border-slate-100">
         <div className="flex justify-between items-center mb-10">
            <button onClick={() => setIsAdding(!isAdding)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg">
               {isAdding ? <X /> : <Plus />} {isAdding ? 'إلغاء' : 'إعلان جديد'}
            </button>
            <h3 className="text-2xl font-black text-slate-800">إدارة البنرات</h3>
         </div>

         {isAdding && (
            <div className="space-y-4 mb-10 bg-slate-50 p-8 rounded-[3rem] animate-in zoom-in">
               <input value={newAd.title} onChange={e => setNewAd({...newAd, title: e.target.value})} placeholder="عنوان الإعلان الرئيسي" className="w-full p-5 rounded-2xl text-right font-black shadow-inner bg-white" />
               <input value={newAd.description} onChange={e => setNewAd({...newAd, description: e.target.value})} placeholder="وصف جانبي (اختياري)" className="w-full p-5 rounded-2xl text-right font-bold text-sm shadow-inner bg-white" />
               <input value={newAd.imageUrl} onChange={e => setNewAd({...newAd, imageUrl: e.target.value})} placeholder="رابط صورة الإعلان (URL)" className="w-full p-5 rounded-2xl text-left font-bold text-xs shadow-inner bg-white" dir="ltr" />
               <button onClick={handleSave} className="w-full bg-slate-950 text-white py-6 rounded-3xl font-black shadow-2xl active:scale-95 transition-all">نشر الإعلان فوراً</button>
            </div>
         )}

         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {ads.map(ad => (
               <div key={ad.id} className="group relative rounded-[2.5rem] overflow-hidden shadow-xl border border-slate-100">
                  <img src={ad.imageUrl} className="w-full h-48 object-cover group-hover:scale-110 transition-transform duration-700" />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-950 p-6 flex flex-col justify-end">
                     <h4 className="text-white font-black text-lg">{ad.title}</h4>
                     <p className="text-[10px] text-slate-400 font-bold">{ad.description}</p>
                  </div>
                  <button onClick={async () => await deleteDoc(doc(db, "ads", ad.id))} className="absolute top-4 left-4 bg-rose-500 text-white p-3 rounded-2xl shadow-xl active:scale-90 transition-all opacity-0 group-hover:opacity-100">
                     <Trash2 className="h-5 w-5" />
                  </button>
               </div>
            ))}
         </div>
      </div>
    </div>
  );
};

