const RestaurantManager: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [restData, setRestData] = useState({ name: '', category: 'مشويات', photoURL: '', menuImageURL: '' });

  const fileRef = useRef<HTMLInputElement>(null);
  const menuImgRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleSave = async () => {
    if (!restData.name) return alert('أدخل الاسم');
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, address: 'المنوفية', lat: 30.5, lng: 31.0
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menuImageURL: '' });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const handleImg = (e: React.ChangeEvent<HTMLInputElement>, field: 'photoURL' | 'menuImageURL') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setRestData({...restData, [field]: reader.result as string});
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-8 animate-reveal">
      <div className="bg-white p-10 rounded-[4rem] shadow-sm border border-slate-100">
         <div className="flex justify-between items-center mb-10">
            <button onClick={() => setIsAdding(!isAdding)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs shadow-lg active:scale-95 transition-all">
               {isAdding ? <X className="h-4 w-4" /> : <Plus className="h-4 w-4" />} {isAdding ? 'إلغاء' : 'إضافة مطعم جديد'}
            </button>
            <h3 className="text-2xl font-black text-slate-800">إدارة المطاعم والمنيو</h3>
         </div>

         {isAdding && (
            <div className="bg-slate-50 p-8 rounded-[3rem] mb-10 space-y-6 border-2 border-emerald-500/10 animate-in slide-in-from-top">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} placeholder="اسم المطعم" className="p-5 rounded-2xl outline-none text-right font-black shadow-inner" />
                  <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} placeholder="التصنيف (مثلاً: بيتزا)" className="p-5 rounded-2xl outline-none text-right font-black shadow-inner" />

                  <div onClick={() => fileRef.current?.click()} className="p-10 border-4 border-dashed border-slate-200 rounded-3xl text-center cursor-pointer hover:bg-white transition-all overflow-hidden relative">
                     {restData.photoURL ? <img src={restData.photoURL} className="absolute inset-0 w-full h-full object-cover" /> : <div className="space-y-2"><Camera className="h-10 w-10 text-slate-300 mx-auto" /><p className="text-[10px] font-black text-slate-300">صورة الغلاف</p></div>}
                     <input type="file" ref={fileRef} hidden onChange={e => handleImg(e, 'photoURL')} />
                  </div>

                  <div onClick={() => menuImgRef.current?.click()} className="p-10 border-4 border-dashed border-slate-200 rounded-3xl text-center cursor-pointer hover:bg-white transition-all overflow-hidden relative">
                     {restData.menuImageURL ? <img src={restData.menuImageURL} className="absolute inset-0 w-full h-full object-cover" /> : <div className="space-y-2"><FileText className="h-10 w-10 text-slate-300 mx-auto" /><p className="text-[10px] font-black text-slate-300">صورة المنيو</p></div>}
                     <input type="file" ref={menuImgRef} hidden onChange={e => handleImg(e, 'menuImageURL')} />
                  </div>
               </div>
               <button onClick={handleSave} disabled={loading} className="w-full bg-slate-950 text-white py-6 rounded-3xl font-black shadow-2xl active:scale-95 transition-all">
                  {loading ? <Loader2 className="animate-spin h-6 w-6 mx-auto" /> : 'نشر المطعم في التطبيق'}
               </button>
            </div>
         )}

         <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {restaurants.map(rest => (
              <div key={rest.id} className="bg-slate-50 p-6 rounded-[2.5rem] flex flex-col gap-4 border border-transparent hover:border-emerald-500 transition-all group">
                 <div className="flex justify-between items-start">
                    <button onClick={async () => { if(confirm('حذف؟')) await deleteDoc(doc(db, "restaurants", rest.id)); }} className="p-3 bg-rose-50 text-rose-400 rounded-xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 className="h-4 w-4" /></button>
                    <div className="text-right">
                       <p className="font-black text-xl text-slate-800">{rest.name}</p>
                       <p className="text-[10px] font-bold text-emerald-600">{rest.category}</p>
                    </div>
                 </div>
                 <div className="w-full h-32 rounded-2xl overflow-hidden bg-slate-200">
                    {rest.photoURL && <img src={rest.photoURL} className="w-full h-full object-cover" />}
                 </div>
              </div>
            ))}
         </div>
      </div>
    </div>
  );
};

