// --- مكون إدارة الجغرافيا (قسم الجغرافيا) ---
const GeographyManager: React.FC = () => {
  const [districts, setDistricts] = useState<District[]>([]);
  const [activeDistrictId, setActiveDistrictId] = useState<string | null>(null);
  const [newDistName, setNewDistName] = useState('');
  const [newVillage, setNewVillage] = useState({ name: '', lat: 30.5, lng: 31.0 });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    return onSnapshot(doc(db, "settings", "geography"), (snap) => {
      if (snap.exists()) setDistricts(snap.data().districts || []);
      else setDistricts(STATIC_DATA); // التحميل المبدئي من الثوابت
    });
  }, []);

  const saveToFirebase = async (data: District[]) => {
    setLoading(true);
    try {
      await setDoc(doc(db, "settings", "geography"), { districts: data, updatedAt: Date.now() });
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  const addDistrict = () => {
    if (!newDistName.trim()) return;
    const newList = [...districts, { id: `dist_${Date.now()}`, name: newDistName, villages: [] }];
    setDistricts(newList);
    setNewDistName('');
    saveToFirebase(newList);
  };

  const deleteDistrict = (id: string) => {
    if (!confirm('سيتم حذف المركز بكل قراه، هل أنت متأكد؟')) return;
    const newList = districts.filter(d => d.id !== id);
    setDistricts(newList);
    saveToFirebase(newList);
  };

  const addVillage = (distId: string) => {
    if (!newVillage.name.trim()) return;
    const newList = districts.map(d => {
      if (d.id === distId) {
        return { ...d, villages: [...d.villages, { id: `vill_${Date.now()}`, name: newVillage.name, center: { lat: newVillage.lat, lng: newVillage.lng } }] };
      }
      return d;
    });
    setDistricts(newList);
    setNewVillage({ name: '', lat: 30.5, lng: 31.0 });
    saveToFirebase(newList);
  };

  const deleteVillage = (distId: string, villId: string) => {
    const newList = districts.map(d => {
      if (d.id === distId) {
        return { ...d, villages: d.villages.filter(v => v.id !== villId) };
      }
      return d;
    });
    setDistricts(newList);
    saveToFirebase(newList);
  };

  return (
    <div className="space-y-8 animate-reveal" dir="rtl">
       <div className="bg-white p-10 rounded-[4rem] shadow-xl border border-slate-100 space-y-12">
          <div className="text-right flex items-center justify-between">
             <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tight">قسم الجغرافيا (إدارة المناطق)</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">إضافة مراكز وقرى محافظة المنوفية والتحكم في إحداثياتها</p>
             </div>
             <div className="bg-emerald-600 p-5 rounded-[2.5rem] text-white shadow-2xl animate-bounce-slow"><Globe2 className="h-8 w-8" /></div>
          </div>

          {/* إضافة مركز جديد */}
          <div className="bg-slate-50 p-8 rounded-[3rem] border-2 border-slate-100 flex flex-col md:flex-row gap-4 items-center">
             <input value={newDistName} onChange={e => setNewDistName(e.target.value)} placeholder="اسم المركز الجديد (مثل: الباجور)" className="flex-1 bg-white p-5 rounded-2xl font-black outline-none text-right border-2 border-transparent focus:border-emerald-500" />
             <button onClick={addDistrict} className="bg-slate-950 text-white px-10 py-5 rounded-2xl font-black flex items-center gap-3 active:scale-95 transition-all">
                <PlusCircle className="h-5 w-5 text-emerald-400" /> إضافة مركز
             </button>
          </div>

          {/* قائمة المراكز والقرى */}
          <div className="grid grid-cols-1 gap-6">
             {districts.map(dist => (
               <div key={dist.id} className="bg-white rounded-[3.5rem] border-2 border-slate-50 shadow-sm overflow-hidden group">
                  <div className="bg-slate-900 p-8 flex justify-between items-center text-white">
                     <div className="flex items-center gap-4">
                        <button onClick={() => deleteDistrict(dist.id)} className="p-3 bg-rose-500/20 text-rose-400 rounded-xl hover:bg-rose-500 hover:text-white transition-all"><Trash2 size={16} /></button>
                        <h4 className="text-xl font-black">{dist.name}</h4>
                     </div>
                     <span className="bg-white/10 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{dist.villages.length} قرية/عزبة</span>
                  </div>

                  <div className="p-8 space-y-6">
                     {/* إضافة قرية داخل المركز */}
                     <div className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100">
                        <input value={activeDistrictId === dist.id ? newVillage.name : ''} onChange={e => { setActiveDistrictId(dist.id); setNewVillage({...newVillage, name: e.target.value}); }} placeholder="اسم القرية" className="bg-white p-4 rounded-xl font-bold text-xs outline-none text-right" />
                        <input type="number" value={activeDistrictId === dist.id ? newVillage.lat : 30.5} onChange={e => { setActiveDistrictId(dist.id); setNewVillage({...newVillage, lat: Number(e.target.value)}); }} placeholder="Lat" className="bg-white p-4 rounded-xl font-bold text-xs outline-none text-center" />
                        <input type="number" value={activeDistrictId === dist.id ? newVillage.lng : 31.0} onChange={e => { setActiveDistrictId(dist.id); setNewVillage({...newVillage, lng: Number(e.target.value)}); }} placeholder="Lng" className="bg-white p-4 rounded-xl font-bold text-xs outline-none text-center" />
                        <button onClick={() => addVillage(dist.id)} className="bg-emerald-600 text-white font-black text-xs rounded-xl py-4 active:scale-95 transition-all">إضافة قرية</button>
                     </div>

                     {/* عرض القرى الحالية */}
                     <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        {dist.villages.map(v => (
                          <div key={v.id} className="p-4 bg-white border border-slate-100 rounded-2xl flex justify-between items-center hover:shadow-md transition-all">
                             <button onClick={() => deleteVillage(dist.id, v.id)} className="text-rose-300 hover:text-rose-500"><X size={14} /></button>
                             <div className="text-right">
                                <p className="font-black text-slate-800 text-xs">{v.name}</p>
                                <p className="text-[8px] text-slate-400 font-mono tracking-tighter" dir="ltr">{v.center.lat.toFixed(4)}, {v.center.lng.toFixed(4)}</p>
                             </div>
                          </div>
                        ))}
                     </div>
                  </div>
               </div>
             ))}
          </div>

          {loading && (
             <div className="fixed inset-0 bg-white/50 backdrop-blur-sm z-[15000] flex items-center justify-center">
                <div className="bg-slate-950 text-white p-10 rounded-[3rem] shadow-2xl flex flex-col items-center gap-6">
                   <Loader2 className="h-10 w-10 animate-spin text-emerald-400" />
                   <p className="font-black tracking-widest uppercase text-xs">جاري تحديث قاعدة بيانات المنوفية...</p>
                </div>
             </div>
          )}
       </div>
    </div>
  );
};

