@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --brand-emerald: #10b981;
  --brand-emerald-deep: #065f46;
  --slate-950: #020617;
  --slate-900: #0f172a;
  --header-height-mobile: 70px;
  --header-height-desktop: 90px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: #f1f5f9;
  color: var(--slate-900);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  height: 100%;
}

/* Animations */
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}
.shake { animation: shake 0.3s ease-in-out; }

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-slide-down { animation: slideDown 0.3s ease-out forwards; }

/* OTP Inputs */
input[type="text"]:focus, 
input[type="tel"]:focus, 
input[type="email"]:focus, 
input[type="password"]:focus, 
select:focus,
textarea:focus {
  transform: scale(1.005);
  box-shadow: 0 10px 15px -3px rgba(16, 185, 129, 0.1);
}

/* Scrollbar customization */
.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

/* Base Layout Containers */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  height: 100%;
}

/* Ride Hailing Layout Utility - Professional Responsive */
.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}

.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
  box-shadow: 0 -15px 50px -12px rgba(0, 0, 0, 0.15);
  max-height: 88vh;
  overflow-y: auto;
  padding-bottom: calc(6rem + env(safe-area-inset-bottom));
  transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Tablet Overrides */
@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 2rem;
    left: 2rem;
    right: auto;
    width: 420px;
    border-radius: 2.5rem;
    max-height: calc(100% - 4rem);
    padding-bottom: 2rem;
    border: 1px solid #f1f5f9;
  }
}

/* Desktop Overrides */
@media (min-width: 1024px) {
  .rh-layout { 
    flex-direction: row-reverse; 
  }

  .rh-map-view { 
    position: relative; 
    flex: 1; 
    margin: 1.5rem; 
    border-radius: 3rem; 
    overflow: hidden; 
    box-shadow: 0 25px 50px -12px rgba(0,0,0,0.1);
  }

  .rh-ui-panel {
    position: relative;
    width: 460px;
    height: calc(100% - 3rem);
    max-height: none;
    margin: 1.5rem 0 1.5rem 1.5rem;
    border-radius: 3rem;
    box-shadow: 0 10px 30px rgba(0,0,0,0.02);
    border: 1px solid #e2e8f0;
    bottom: auto; 
    left: auto; 
    right: auto;
    padding-bottom: 2rem;
  }
}

.bottom-sheet-grabber {
  width: 48px;
  height: 5px;
  background: #e2e8f0;
  border-radius: 10px;
  margin: 12px auto;
  flex-shrink: 0;
}

@media (min-width: 768px) {
  .bottom-sheet-grabber { display: none; }
}

.app-footer {
  width: 100%;
  text-align: center;
  padding: 2rem 0;
  color: #94a3b8;
  font-weight: 600;
  font-size: 0.75rem;
}

.label-strong { font-weight: 900; color: var(--slate-950); }
.helper-text { font-weight: 600; color: #64748b; font-size: 0.75rem; }

/* Grid Helpers */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 1rem;
}
@media (min-width: 640px) { .stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1280px) { .stats-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }

