      )}

      {activeTab === 'USERS' && (
        <div className="space-y-6 animate-reveal">
           <div className="bg-white p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] shadow-sm border border-slate-50 space-y-6">
              <div className="relative">
                 <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                 <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="بحث عن اسم أو رقم موبايل..." className="w-full bg-slate-50 rounded-[1.5rem] md:rounded-[2rem] py-4 md:py-5 pr-12 pl-6 font-black text-sm outline-none text-right focus:bg-white transition-all shadow-inner" dir="rtl" />
