                      {u.photoURL ? <img src={u.photoURL} className="w-full h-full object-cover" /> : (u.name || 'ع')[0]}
                   </div>
                   <div className="flex-1 min-w-0">
                      <h4 className="font-black text-slate-900 text-xs md:text-sm truncate leading-tight">{u.name}</h4>
                      <div className="flex items-center gap-2 justify-end mt-1.5 flex-wrap">
                         <span className="text-[9px] md:text-[10px] font-black text-emerald-600">{(u.wallet?.balance || 0).toFixed(1)} ج.م</span>
                         <span className={`text-[7px] md:text-[8px] font-black px-2 py-0.5 rounded-full ${u.role === 'DRIVER' ? 'bg-blue-50 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>{u.role}</span>
                         <div className={`w-1.5 h-1.5 rounded-full ${u.status === 'APPROVED' ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
                      </div>
                   </div>
                   <button onClick={() => setEditingUser(u)} className="p-3 md:p-4 bg-slate-50 text-slate-400 rounded-xl md:rounded-2xl active:scale-90 transition-all border border-slate-100 group-hover:bg-emerald-50 group-hover:text-emerald-600">
                      <Edit3 className="h-4 w-4 md:h-5 md:w-5" />
                   </button>
                </div>
              ))}
           </div>
        </div>
      )}

      {/* Rest components keep their logic but gain responsive grid columns */}
      {activeTab === 'RESTAURANTS' && <div className="animate-reveal"><RestaurantManager /></div>}
      {activeTab === 'ADS' && <div className="animate-reveal"><AdManager /></div>}
      {activeTab === 'VILLAGES' && <div className="animate-reveal"><VillageDistrictManager /></div>}
    </div>
  );
};
