const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);
  const [showPrescriptionModal, setShowPrescriptionModal] = useState<string | null>(null);

  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapInstance = useRef<any>(null);
  const watchId = useRef<number | null>(null);
  const driverMarker = useRef<any>(null);

  useEffect(() => {
    if (mapContainerRef.current && !mapInstance.current) {
      mapInstance.current = L.map(mapContainerRef.current, { zoomControl: false, attributionControl: false }).setView([30.556, 31.008], 11);
      L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(mapInstance.current);
    }
  }, []);

  useEffect(() => {
    if (isOnline) {
      if ("geolocation" in navigator) {
        watchId.current = navigator.geolocation.watchPosition(
          (pos) => {
            const { latitude, longitude } = pos.coords;
            updateDoc(doc(db, "users", user.id), {
              location: { lat: latitude, lng: longitude, updatedAt: Date.now() }
            });
            if (mapInstance.current && driverMarker.current) {
               driverMarker.current.setLatLng([latitude, longitude]);
            }
          },
          null, { enableHighAccuracy: true }
        );
      }
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snapshot) => {
      setAvailableOrders(snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  const getDistrictName = (villageName?: string) => {
    return MENOFIA_DATA.find(d => d.villages.some(v => v.name === villageName))?.name || 'المنوفية';
  };

  const handleWhatsAppCustomer = (phone: string) => {
    const msg = `مرحباً، أنا كابتن "وصـــلــهــا"، أنا في طريقي إليك الآن.`;
    window.open(`https://wa.me/2${phone}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const handleSendOffer = async (orderId: string) => {
    const price = parseFloat(offerPrice);
    if (!price || price <= 0 || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "offers"), {
        orderId: orderId, driverId: user.id, driverName: user.name, driverPhone: user.phone,
        driverRating: 5.0, vehicleType: user.vehicleType || 'TOKTOK', price: price, createdAt: Date.now()
      });
      setShowOfferInput(null);
      setOfferPrice('');
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const updateOrderStatus = async (status: OrderStatus) => {
    if (!activeOrder || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const updates: any = { status };
      if (status === OrderStatus.DELIVERED) updates.deliveredAt = Date.now();
      await updateDoc(doc(db, "orders", activeOrder.id), updates);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (user.status !== 'APPROVED') {
     return (
       <div className="p-10 md:p-20 text-center font-black flex flex-col items-center justify-center h-screen space-y-6">
          <div className="bg-amber-50 p-8 rounded-[3rem] animate-pulse">
            <ShieldAlert className="h-16 w-16 text-amber-500" />
          </div>
          <h2 className="text-xl md:text-2xl tracking-tighter">حسابك قيد المراجعة في المنوفية...</h2>
          <p className="text-xs text-slate-400 max-w-xs">سيتم تفعيل حسابك من قبل الإدارة المركزية فور مراجعة المستندات.</p>
       </div>
     );
  }

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      {showPrescriptionModal && <PrescriptionModal url={showPrescriptionModal} onClose={() => setShowPrescriptionModal(null)} />}

      <div ref={mapContainerRef} className={`rh-map-view absolute inset-0 z-0 transition-opacity duration-500 ${activeView === 'MAP' ? 'opacity-100 block' : 'opacity-0 hidden lg:block'}`}></div>

      <div className={`rh-ui-panel no-scrollbar px-5 md:px-6 space-y-6 md:space-y-8 pb-32 pt-6 md:pt-8 animate-in fade-in overflow-y-auto z-[100] ${activeView === 'MAP' ? 'translate-y-full lg:translate-y-0 opacity-0 lg:opacity-100' : 'translate-y-0 opacity-100 bg-slate-50'}`}>
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="max-w-2xl mx-auto space-y-6 md:space-y-8">
            <div className={`p-8 md:p-10 rounded-[2.5rem] md:rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div className="text-right">
                  <h2 className="text-2xl md:text-3xl font-black tracking-tighter">{isOnline ? 'نشط في المنوفية' : 'متوقف'}</h2>
                  <p className="text-[9px] md:text-[10px] font-black opacity-60 mt-1.5 uppercase tracking-widest">تغطية كاملة للمحافظة</p>
               </div>
               <button onClick={() => setIsOnline(!isOnline)} className={`p-5 md:p-6 rounded-[1.5rem] md:rounded-[2.5rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}><Power className="h-8 w-8 md:h-10 md:w-10" /></button>
            </div>

            {activeOrder ? (
               <div className="bg-white rounded-[2.5rem] md:rounded-[4rem] shadow-2xl p-8 md:p-10 space-y-8 md:space-y-10 animate-in zoom-in border-t-8 border-t-emerald-500">
                  <div className="flex justify-between items-center">
                     <div className="flex items-center gap-2 md:gap-3 flex-wrap justify-end">
                        <span className="bg-emerald-100 text-emerald-700 px-4 md:px-6 py-1.5 md:py-2 rounded-full text-[9px] md:text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span>
                        {activeOrder.passengerCount && (
                          <span className="bg-blue-50 text-blue-600 px-3 md:px-4 py-1.5 md:py-2 rounded-full text-[9px] md:text-[10px] font-black flex items-center gap-1.5 md:gap-2">
                             <UsersIcon className="h-3 w-3" /> {activeOrder.passengerCount} فرد
                          </span>
                        )}
                     </div>
                     <p className="text-4xl md:text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-sm md:text-lg opacity-30 font-bold uppercase">ج.م</span></p>
                  </div>

                  {activeOrder.category === 'PHARMACY' && (
                    <div className="space-y-4 animate-reveal">
                       <div className="bg-sky-50 border-2 border-sky-100 p-6 md:p-8 rounded-[2rem] md:rounded-[3rem] text-right space-y-4 shadow-inner">
                          <div className="flex items-center justify-between">
                            <p className="text-[9px] md:text-[10px] font-black text-sky-600 uppercase tracking-[0.2em]">طلب صيدلية مرفق</p>
                            <Pill className="h-5 w-5 text-sky-400" />
                          </div>
                          {activeOrder.notes && (
                            <div className="bg-white/80 p-4 rounded-2xl border border-sky-100">
                               <p className="text-xs font-bold text-slate-700 leading-relaxed">{activeOrder.notes}</p>
                            </div>
                          )}
                          {activeOrder.prescriptionImage && (
                            <div onClick={() => setShowPrescriptionModal(activeOrder.prescriptionImage!)} className="w-full h-44 md:h-56 bg-white rounded-[1.5rem] md:rounded-[2rem] overflow-hidden border-2 border-dashed border-sky-200 cursor-pointer shadow-sm relative">
                               <img src={activeOrder.prescriptionImage} className="w-full h-full object-cover" />
                               <div className="absolute inset-0 bg-black/10 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity"><ZoomIn className="text-white h-8 w-8" /></div>
                            </div>
                          )}
                       </div>
                    </div>
                  )}

                  <div className="space-y-6 md:space-y-8 text-right">
                     <div className="flex gap-4 md:gap-6 items-start flex-row-reverse">
                        <div className="bg-slate-50 p-4 md:p-5 rounded-[1.5rem] md:rounded-3xl text-emerald-600 shrink-0 shadow-inner"><MapPin className="h-6 w-6 md:h-8 md:w-8" /></div>
                        <div className="flex-1">
                           <p className="helper-text uppercase mb-1 md:mb-2 tracking-widest">مسار المشوار</p>
                           <p className="font-black text-lg md:text-2xl text-slate-950 leading-tight mb-4">
                             {activeOrder.pickup?.villageName} <ArrowLeft className="h-4 w-4 inline text-emerald-500" /> {activeOrder.dropoff?.villageName}
                           </p>

                           <div className="space-y-2 md:space-y-3">
                              {activeOrder.pickupNotes && (
                                <div className="bg-emerald-50/50 p-4 rounded-2xl border border-emerald-100 flex items-start gap-3 flex-row-reverse">
                                   <Info className="h-4 w-4 text-emerald-500 mt-0.5 shrink-0" />
                                   <div className="text-right flex-1">
                                      <p className="text-[8px] md:text-[9px] font-black text-emerald-600 uppercase">وصف الاستلام:</p>
                                      <p className="text-xs font-bold text-slate-700 line-clamp-2">{activeOrder.pickupNotes}</p>
                                   </div>
                                </div>
                              )}
                              {activeOrder.dropoffNotes && (
                                <div className="bg-rose-50/50 p-4 rounded-2xl border border-rose-100 flex items-start gap-3 flex-row-reverse">
                                   <Info className="h-4 w-4 text-rose-500 mt-0.5 shrink-0" />
                                   <div className="text-right flex-1">
                                      <p className="text-[8px] md:text-[9px] font-black text-rose-600 uppercase">وصف الوصول:</p>
                                      <p className="text-xs font-bold text-slate-700 line-clamp-2">{activeOrder.dropoffNotes}</p>
                                   </div>
                                </div>
                              )}
                           </div>
                        </div>
                     </div>
                  </div>
                  <div className="grid grid-cols-3 gap-2 md:gap-4 pt-4">
                     <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-4 md:py-6 rounded-[1.2rem] md:rounded-[2rem] font-black text-lg flex items-center justify-center shadow-xl active:scale-95 transition-all"><PhoneCall className="h-6 w-6" /></a>
                     <button onClick={() => handleWhatsAppCustomer(activeOrder.customerPhone)} className="bg-[#25D366] text-white py-4 md:py-6 rounded-[1.2rem] md:rounded-[2rem] font-black text-lg flex items-center justify-center shadow-xl active:scale-95 transition-all"><MessageCircle className="h-6 w-6" /></button>
                     <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-4 md:py-6 rounded-[1.2rem] md:rounded-[2rem] font-black text-lg flex items-center justify-center active:scale-95 relative transition-all"><Bot className="h-6 w-6" /></button>
                     <button onClick={() => updateOrderStatus(activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED)} disabled={isSubmitting} className="col-span-full bg-emerald-600 text-white py-6 md:py-8 rounded-[1.8rem] md:rounded-[2.5rem] font-black text-xl md:text-2xl shadow-2xl active:scale-95 mt-2 animate-glow">
                        {isSubmitting ? <Loader2 className="h-8 w-8 md:h-10 md:w-10 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد الاستلام' : 'تم التوصيل والتحصيل'}
                     </button>
                  </div>
               </div>
