      <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-2xl border-t border-slate-100 p-6 md:p-8 flex justify-around items-center z-[200] shadow-[0_-20px_50px_rgba(0,0,0,0.12)]">
         {[
           {id: 'HOME', icon: <Home className="h-6 w-6 md:h-7 md:w-7" />, label: 'الرئيسية'},
           {id: 'MAP', icon: <MapIcon className="h-6 w-6 md:h-7 md:w-7" />, label: 'الخريطة'},
           {id: 'ACTIVITY', icon: <History className="h-6 w-6 md:h-7 md:w-7" />, label: 'سجلي'},
           {id: 'PROFILE', icon: <UserIcon className="h-6 w-6 md:h-7 md:w-7" />, label: 'حسابي'}
