                {adData.imageUrl ? <img src={adData.imageUrl} className="w-full h-full object-cover" /> : <Camera className="h-12 w-12 text-indigo-200" />}
                <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
