             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input value={adData.title} onChange={e => setAdData({...adData, title: e.target.value})} placeholder="عنوان الإعلان" className="bg-white p-5 rounded-2xl font-black text-sm outline-none text-right" />
                <select value={adData.type} onChange={e => setAdData({...adData, type: e.target.value as any})} className="bg-white p-5 rounded-2xl font-black text-sm outline-none text-right appearance-none">
                   <option value="special_offer">عرض خاص</option>
                   <option value="restaurant">مطعم</option>
                   <option value="service">خدمة</option>
                   <option value="general">عام</option>
