};

// --- Restaurant Manager ---
const RestaurantManager: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);

  const [restData, setRestData] = useState({ 
    name: '', 
    category: 'مشويات', 
    photoURL: '', 
    menuImageURL: '',
    address: 'المنوفية'
  });

  const [newItem, setNewItem] = useState({ name: '', price: 0, photoURL: '' });
  const [activeRestId, setActiveRestId] = useState<string | null>(null);

  const fileRef = useRef<HTMLInputElement>(null);
  const menuImgRef = useRef<HTMLInputElement>(null);
  const itemFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'PHOTO' | 'MENU' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      if (target === 'PHOTO') setRestData(prev => ({ ...prev, photoURL: base64 }));
      if (target === 'MENU') setRestData(prev => ({ ...prev, menuImageURL: base64 }));
      if (target === 'ITEM') setNewItem(prev => ({ ...prev, photoURL: base64 }));
    };
    reader.readAsDataURL(file);
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, lat: 30.556, lng: 31.008
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menuImageURL: '', address: 'المنوفية' });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
    await updateDoc(doc(db, "restaurants", rid), { menu });
    setNewItem({ name: '', price: 0, photoURL: '' });
  };

  return (
    <div className="space-y-8">
      <div className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-sm">
        <div className="flex justify-between items-center mb-8 flex-row-reverse">
           <h3 className="text-xl font-black text-slate-900 flex items-center gap-3">إدارة المطاعم <Store className="text-emerald-500" /></h3>
           <button onClick={() => setIsAdding(!isAdding)} className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-black text-xs flex items-center gap-2 shadow-xl active:scale-95 transition-all">
              {isAdding ? <X className="h-4 w-4" /> : <PlusCircle className="h-4 w-4" />}
              {isAdding ? 'إلغاء' : 'إضافة مطعم جديد'}
           </button>
        </div>

        {isAdding && (
          <div className="bg-slate-50 p-8 rounded-[3rem] mb-10 space-y-8 border-2 border-emerald-500/10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
               <div onClick={() => fileRef.current?.click()} className="w-full h-48 bg-white rounded-3xl border-4 border-dashed border-emerald-100 flex items-center justify-center cursor-pointer overflow-hidden relative group">
                  {restData.photoURL ? <img src={restData.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-10 w-10 text-emerald-200" />}
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-black text-xs uppercase tracking-widest">صورة المطعم</div>
               </div>
               <div onClick={() => menuImgRef.current?.click()} className="w-full h-48 bg-white rounded-3xl border-4 border-dashed border-amber-100 flex items-center justify-center cursor-pointer overflow-hidden relative group">
                  {restData.menuImageURL ? <img src={restData.menuImageURL} className="w-full h-full object-cover" /> : <FileText className="h-10 w-10 text-amber-200" />}
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center text-white font-black text-xs uppercase tracking-widest">صورة المنيو</div>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} placeholder="اسم المطعم" className="bg-white p-5 rounded-2xl font-black text-sm outline-none text-right" />
               <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} placeholder="التصنيف" className="bg-white p-5 rounded-2xl font-black text-sm outline-none text-right" />
            </div>
            <button onClick={saveRestaurant} disabled={loading} className="w-full bg-emerald-600 text-white py-6 rounded-3xl font-black shadow-2xl active:scale-95 transition-all">
               {loading ? <Loader2 className="animate-spin h-6 w-6 mx-auto" /> : 'حفظ بيانات المطعم'}
            </button>
            <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'PHOTO')} />
            <input type="file" ref={menuImgRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'MENU')} />
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
           {restaurants.map(rest => (
             <div key={rest.id} className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 flex flex-col gap-6">
                <div className="flex justify-between items-start flex-row-reverse">
                   <div className="flex items-center gap-4 flex-row-reverse text-right">
                      <div className="w-14 h-14 bg-white rounded-2xl overflow-hidden shadow-sm">
                         {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Store className="p-3 text-slate-200" />}
                      </div>
                      <div>
                        <h4 className="font-black text-lg text-slate-900">{rest.name}</h4>
                        <p className="text-[10px] font-bold text-emerald-600">{rest.category}</p>
                      </div>
                   </div>
                   <button onClick={async () => { if(confirm('حذف المطعم؟')) await deleteDoc(doc(db, "restaurants", rest.id)); }} className="bg-rose-50 p-2.5 rounded-xl text-rose-500 hover:bg-rose-500 hover:text-white transition-all"><Trash2 className="h-4 w-4" /></button>
                </div>

                <div className="space-y-3">
                   <h5 className="text-[9px] font-black text-slate-400 uppercase tracking-widest text-right px-2">الوجبات ({rest.menu?.length || 0})</h5>
                   <div className="grid gap-2">
                      {rest.menu?.map(item => (
                        <div key={item.id} className="bg-white p-3 rounded-2xl flex justify-between items-center flex-row-reverse shadow-sm">
                           <div className="flex items-center gap-3 flex-row-reverse">
                              <div className="w-10 h-10 rounded-xl bg-slate-50 overflow-hidden border border-slate-100">
                                 {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <Utensils className="p-2.5 text-slate-200" />}
                              </div>
                              <div className="text-right">
                                <p className="font-black text-xs text-slate-800">{item.name}</p>
                                <p className="text-[10px] font-bold text-emerald-600">{item.price} ج.م</p>
                              </div>
                           </div>
                           <button onClick={async () => {
                             const menu = rest.menu.filter(i => i.id !== item.id);
                             await updateDoc(doc(db, "restaurants", rest.id), { menu });
                           }} className="text-rose-200 hover:text-rose-500 transition-colors"><X className="h-4 w-4" /></button>
                        </div>
                      ))}
                   </div>

                   <div className="bg-white p-5 rounded-[2rem] border border-slate-100 space-y-4">
                      <div className="flex gap-3 flex-row-reverse">
                         <div onClick={() => { setActiveRestId(rest.id); itemFileRef.current?.click(); }} className="w-12 h-12 bg-slate-50 rounded-xl border-2 border-dashed border-emerald-200 flex items-center justify-center cursor-pointer shrink-0 overflow-hidden">
                            {activeRestId === rest.id && newItem.photoURL ? <img src={newItem.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-4 w-4 text-emerald-200" />}
                         </div>
                         <div className="flex-1 space-y-2">
                            <input value={activeRestId === rest.id ? newItem.name : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, name: e.target.value}); }} placeholder="اسم الوجبة" className="w-full bg-slate-50 p-3 rounded-xl text-[10px] font-black outline-none text-right" />
                            <div className="flex gap-2">
                               <input type="number" value={activeRestId === rest.id ? (newItem.price || '') : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, price: Number(e.target.value)}); }} placeholder="السعر" className="flex-1 bg-slate-50 p-3 rounded-xl text-[10px] font-black outline-none text-right" />
                               <button onClick={() => addMenuItem(rest.id)} className="bg-emerald-600 text-white px-4 py-2 rounded-xl font-black text-[10px]">إضافة</button>
                            </div>
                         </div>
                      </div>
                      <input type="file" ref={itemFileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'ITEM')} />
                   </div>
                </div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

