                <input type="number" value={settings.basePrice} onChange={e => setSettings({...settings, basePrice: Number(e.target.value)})} className="w-full bg-slate-50 rounded-2xl p-5 font-black text-sm outline-none border-2 border-transparent focus:border-emerald-500" />
             </div>
