                <input type="number" value={settings.pricePerKm} onChange={e => setSettings({...settings, pricePerKm: Number(e.target.value)})} className="w-full bg-slate-50 rounded-2xl p-5 font-black text-sm outline-none border-2 border-transparent focus:border-emerald-500" />
