                           <p className="text-[11px] font-bold text-slate-500 hover:text-emerald-600 transition-colors cursor-default">{v.name}</p>
                        </div>
                      ))}
                   </div>
                </div>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

