import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

// Types
import type { Restaurant, MenuItem, User } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, doc, onSnapshot, 
  setDoc, deleteDoc, updateDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  ArrowRight, Store, Plus, X, Trash2, Edit3, 
  Camera, FileText, Loader2, Save, Utensils,
  PlusCircle, Circle, MapPin, Search
} from 'lucide-react';

const AdminRestaurantManager: React.FC<{ user: User }> = ({ user }) => {
  const navigate = useNavigate();
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const [restData, setRestData] = useState({ 
    name: '', category: 'مشويات', photoURL: '', menuImageURL: '', address: 'المنوفية'
  });

  const [newItem, setNewItem] = useState({ name: '', price: 0, photoURL: '' });
  const [activeRestId, setActiveRestId] = useState<string | null>(null);

  const fileRef = useRef<HTMLInputElement>(null);
  const menuImgRef = useRef<HTMLInputElement>(null);
  const itemFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, target: 'PHOTO' | 'MENU' | 'ITEM') => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64 = reader.result as string;
      if (target === 'PHOTO') setRestData(prev => ({ ...prev, photoURL: base64 }));
      if (target === 'MENU') setRestData(prev => ({ ...prev, menuImageURL: base64 }));
      if (target === 'ITEM') setNewItem(prev => ({ ...prev, photoURL: base64 }));
    };
    reader.readAsDataURL(file);
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, lat: 30.556, lng: 31.008
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', menuImageURL: '', address: 'المنوفية' });
    } catch (e) { alert('خطأ في الحفظ'); } finally { setLoading(false); }
  };

  const addMenuItem = async (rid: string) => {
    if (!newItem.name || newItem.price <= 0) return;
    const rest = restaurants.find(r => r.id === rid);
    if (!rest) return;
    const menu = [...(rest.menu || []), { ...newItem, id: `item_${Date.now()}` }];
    await updateDoc(doc(db, "restaurants", rid), { menu });
    setNewItem({ name: '', price: 0, photoURL: '' });
  };

  return (
    <div className="max-w-6xl mx-auto p-6 md:p-10 space-y-10 animate-in slide-in-from-bottom duration-500 text-right pb-32" dir="rtl">
      {/* Header */}
      <div className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-5">
           <div className="bg-emerald-600 p-4 rounded-3xl text-white shadow-xl">
              <Store className="h-8 w-8" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tighter">إدارة دليل المطاعم</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">تحديث المنشورات وقوائم الطعام</p>
           </div>
        </div>
        <button onClick={() => navigate('/')} className="p-4 bg-white border border-slate-100 rounded-2xl shadow-sm text-slate-400 hover:text-emerald-600 flex items-center gap-2">
          <span className="font-black text-xs">رجوع</span>
          <ArrowRight className="h-5 w-5" />
        </button>
      </div>

      {/* Control Bar */}
      <div className="bg-white p-6 rounded-[3rem] shadow-sm border border-slate-50 flex flex-col md:flex-row-reverse gap-4 justify-between items-center">
         <div className="relative flex-1 w-full max-w-md group">
            <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-emerald-500 transition-colors" />
            <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="بحث عن اسم مطعم..." className="w-full bg-slate-50 rounded-[1.8rem] py-4 pr-14 pl-6 font-black text-xs outline-none focus:bg-white transition-all shadow-inner" />
         </div>
         <button onClick={() => setIsAdding(!isAdding)} className="bg-slate-900 text-white px-10 py-4 rounded-[1.8rem] font-black text-xs flex items-center gap-3 shadow-xl active:scale-95 transition-all">
            {isAdding ? <X className="h-4 w-4" /> : <PlusCircle className="h-4 w-4" />}
            {isAdding ? 'إلغاء الإضافة' : 'إضافة مطعم جديد'}
         </button>
      </div>

      {isAdding && (
        <div className="bg-white p-10 rounded-[3.5rem] shadow-2xl space-y-10 animate-in zoom-in border-4 border-emerald-50">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
              <div onClick={() => fileRef.current?.click()} className="w-full h-56 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-emerald-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden relative group">
                 {restData.photoURL ? <img src={restData.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-12 w-12 text-emerald-200 mb-2" />}
                 {!restData.photoURL && <p className="text-[10px] font-black text-emerald-300 uppercase tracking-widest">صورة المطعم الرئيسية</p>}
                 <input type="file" ref={fileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'PHOTO')} />
              </div>
              <div onClick={() => menuImgRef.current?.click()} className="w-full h-56 bg-slate-50 rounded-[2.5rem] border-4 border-dashed border-amber-100 flex flex-col items-center justify-center cursor-pointer overflow-hidden relative group">
                 {restData.menuImageURL ? <img src={restData.menuImageURL} className="w-full h-full object-cover" /> : <FileText className="h-12 w-12 text-amber-200 mb-2" />}
                 {!restData.menuImageURL && <p className="text-[10px] font-black text-amber-300 uppercase tracking-widest">صورة المنيو الورقي</p>}
                 <input type="file" ref={menuImgRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'MENU')} />
              </div>
           </div>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} placeholder="اسم المطعم" className="bg-slate-50 p-6 rounded-2xl font-black text-sm outline-none text-right border-2 border-transparent focus:border-emerald-500" />
              <input value={restData.category} onChange={e => setRestData({...restData, category: e.target.value})} placeholder="تصنيف الطعام" className="bg-slate-50 p-6 rounded-2xl font-black text-sm outline-none text-right border-2 border-transparent focus:border-emerald-500" />
           </div>
           <button onClick={saveRestaurant} disabled={loading} className="w-full bg-emerald-600 text-white py-7 rounded-[2rem] font-black text-lg shadow-2xl active:scale-95 transition-all">
              {loading ? <Loader2 className="animate-spin h-6 w-6 mx-auto" /> : 'حفظ ونشر المطعم'}
           </button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
         {restaurants.filter(r => r.name.includes(searchTerm)).map(rest => (
           <div key={rest.id} className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-xl flex flex-col gap-8 group hover:border-emerald-500 transition-all">
              <div className="flex justify-between items-start flex-row-reverse">
                 <div className="flex items-center gap-5 flex-row-reverse text-right">
                    <div className="w-20 h-20 bg-slate-900 rounded-[2rem] overflow-hidden shadow-2xl border-4 border-white">
                       {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <Building2 className="p-5 text-emerald-400" />}
                    </div>
                    <div>
                      <h4 className="font-black text-2xl text-slate-950 leading-tight">{rest.name}</h4>
                      <p className="text-xs font-bold text-emerald-600 uppercase tracking-widest mt-1">{rest.category}</p>
                    </div>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={async () => { if(confirm('حذف المطعم؟')) await deleteDoc(doc(db, "restaurants", rest.id)); }} className="bg-rose-50 text-rose-500 p-4 rounded-2xl hover:bg-rose-500 hover:text-white transition-all shadow-sm"><Trash2 className="h-5 w-5" /></button>
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="flex items-center justify-between flex-row-reverse px-2">
                    <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">أصناف المنيو ({rest.menu?.length || 0})</h5>
                    <div className="h-px flex-1 bg-slate-50 mr-4"></div>
                 </div>

                 <div className="grid gap-3 max-h-64 overflow-y-auto no-scrollbar px-1">
                    {rest.menu?.map(item => (
                      <div key={item.id} className="bg-slate-50 p-4 rounded-[2rem] flex justify-between items-center flex-row-reverse border border-transparent hover:border-emerald-100 transition-all">
                         <div className="flex items-center gap-4 flex-row-reverse">
                            <div className="w-12 h-12 rounded-2xl bg-white overflow-hidden border border-slate-100 shrink-0">
                               {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <Utensils className="p-3 text-slate-200" />}
                            </div>
                            <div className="text-right">
                               <p className="font-black text-sm text-slate-800">{item.name}</p>
                               <p className="text-[10px] font-bold text-emerald-600">{item.price} ج.م</p>
                            </div>
                         </div>
                         <button onClick={async () => {
                           const menu = rest.menu.filter(i => i.id !== item.id);
                           await updateDoc(doc(db, "restaurants", rest.id), { menu });
                         }} className="p-2 text-rose-200 hover:text-rose-500 transition-colors"><X className="h-4 w-4" /></button>
                      </div>
                    ))}
                 </div>

                 {/* New Item Form */}
                 <div className="bg-slate-950 p-8 rounded-[2.5rem] space-y-6 shadow-2xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-full bg-white/5 blur-3xl -mr-16"></div>
                    <div className="flex gap-4 flex-row-reverse relative z-10">
                       <div onClick={() => { setActiveRestId(rest.id); itemFileRef.current?.click(); }} className="w-16 h-16 bg-white/10 rounded-2xl border-2 border-dashed border-emerald-500/30 flex items-center justify-center cursor-pointer shrink-0 overflow-hidden hover:bg-white/20 transition-all">
                          {activeRestId === rest.id && newItem.photoURL ? <img src={newItem.photoURL} className="w-full h-full object-cover" /> : <Camera className="h-6 w-6 text-emerald-400" />}
                       </div>
                       <div className="flex-1 space-y-3">
                          <input value={activeRestId === rest.id ? newItem.name : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, name: e.target.value}); }} placeholder="اسم الوجبة" className="w-full bg-white/5 p-4 rounded-xl text-xs font-bold text-white outline-none text-right border border-white/10" />
                          <div className="flex gap-2">
                             <input type="number" value={activeRestId === rest.id ? (newItem.price || '') : ''} onChange={e => { setActiveRestId(rest.id); setNewItem({...newItem, price: Number(e.target.value)}); }} placeholder="السعر" className="flex-1 bg-white/5 p-4 rounded-xl text-xs font-bold text-white outline-none text-right border border-white/10" />
                             <button onClick={() => addMenuItem(rest.id)} className="bg-emerald-600 text-white px-8 rounded-xl font-black text-xs active:scale-90 transition-all">إضافة</button>
                          </div>
                       </div>
                    </div>
                    <input type="file" ref={itemFileRef} className="hidden" accept="image/*" onChange={e => handleImageUpload(e, 'ITEM')} />
                 </div>
              </div>
           </div>
         ))}
      </div>
    </div>
  );
};

