  useEffect(() => {
    // جلب الجغرافيا من Firestore
    const unsubGeo = onSnapshot(collection(db, "geo_config"), (snap) => {
      if (!snap.empty) {
        setGeoData(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[]);
      }
    });

    onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });

    onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });

    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.sort((a, b) => b.createdAt - a.createdAt).find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  // AI Distance Logic
  useEffect(() => {
    const fetchAiDistance = async () => {
      if (!pickupVillage || !dropoffVillage) { setAiRoadDistance(null); return; }
      if (pickupVillage.id === dropoffVillage.id) { setAiRoadDistance(2); return; }
      setIsCalculatingAiDist(true);
      try {
        const straightDist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `قدر المسافة الحقيقية للسيارات بين قرية "${pickupVillage.name}" و قرية "${dropoffVillage.name}" في محافظة المنوفية. المسافة الجوية هي ${straightDist.toFixed(1)} كم. أجب برقم المسافة فقط.`,
        });
        const dist = parseFloat(response.text?.trim() || '0');
        setAiRoadDistance(isNaN(dist) ? parseFloat((straightDist * 1.4).toFixed(1)) : dist);
      } catch (error) {
        setAiRoadDistance(calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng) * 1.4);
      } finally { setIsCalculatingAiDist(false); }
    };
    fetchAiDistance();
  }, [pickupVillage?.id, dropoffVillage?.id]);

  const approxRidePrice = useMemo(() => {
    if (!pickupVillage || !dropoffVillage) return 0;
    const dist = aiRoadDistance || calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
    const multiplier = DEFAULT_PRICING.multipliers[rideVehicleType] || 1;
    if (pickupVillage.id === dropoffVillage.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multiplier), DEFAULT_PRICING.minPrice);
  }, [pickupVillage, dropoffVillage, rideVehicleType, aiRoadDistance]);

  const handleCreateRideOrder = async () => {
    if(!pickupVillage || !dropoffVillage) return;
    setIsSubmitting(true);
    try {
       await addDoc(collection(db, "orders"), {
          customerId: user.id, customerPhone: user.phone, category: 'TAXI',
          pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
          dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
          pickupNotes, dropoffNotes, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), 
          requestedVehicleType: rideVehicleType, price: approxRidePrice, distance: aiRoadDistance || 0,
          operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
       });
    } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}
      {expandedAd && <AdDetailModal ad={expandedAd} onClose={() => setExpandedAd(null)} onAction={(ad) => {
         if (ad.type === 'restaurant' && ad.targetId) {
            const rest = restaurants.find(r => r.id === ad.targetId);
            if (rest) setViewingRestaurant(rest);
         } else { window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent('أريد طلب العرض: ' + ad.title)}`); }
      }} />}

      <div className="rh-ui-panel no-scrollbar z-[100] bg-slate-50">
        <div className="p-5 md:p-12 space-y-8 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div>
                    <h2 className="text-3xl font-black text-slate-950 tracking-tighter">وصـــلــهــا المنوفية</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase mt-1">المحرك الأذكى لتنقلاتك</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-3xl shadow-sm"><Bot /></button>
              </div>

              {ads.length > 0 && (
                <div className="flex gap-4 overflow-x-auto no-scrollbar py-2 scroll-smooth">
                   {ads.filter(ad => ad.isActive).map(ad => (
                     <div key={ad.id} onClick={() => setExpandedAd(ad)} className="min-w-[85%] aspect-video bg-slate-900 rounded-[2.5rem] overflow-hidden relative shadow-xl active:scale-95 transition-all">
                        <img src={ad.imageUrl} className="w-full h-full object-cover opacity-80" />
                        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 flex flex-col justify-end p-6">
                           <h4 className="text-white font-black text-lg">{ad.title}</h4>
                        </div>
                     </div>
                   ))}
                </div>
              )}

              <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'طعام', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'أدوية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-8 rounded-[2.5rem] flex flex-col items-center gap-3 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-8 w-8" }) : cat.icon}
                       <span className="text-[11px] font-black">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'TAXI' && (
                <div className="space-y-6 animate-reveal">
                   <LocationSelector districts={geoData} label="نقطة الانطلاق" helper="موقعك الحالي" icon={<MapPin />} iconBg="bg-emerald-500" selectedDistrict={pickupDistrict} selectedVillage={pickupVillage} notes={pickupNotes} onDistrictSelect={setPickupDistrict} onVillageSelect={setPickupVillage} onNotesChange={setPickupNotes} />
                   <LocationSelector districts={geoData} label="وجهة الوصول" helper="إلى أين نذهب؟" icon={<Check />} iconBg="bg-rose-500" selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes} onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes} />

                   <div className="bg-slate-950 p-8 rounded-[3rem] text-white space-y-6">
                      <div className="text-center space-y-2">
                        <p className="text-[10px] font-black text-emerald-400 tracking-widest uppercase">التكلفة التقريبية (AI)</p>
                        <h3 className="text-5xl font-black">{isCalculatingAiDist ? '...' : approxRidePrice} <span className="text-xs opacity-40">ج.م</span></h3>
                      </div>
                      <button onClick={handleCreateRideOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-xl shadow-2xl active:scale-95 transition-all">اطلب الآن</button>
                   </div>
                </div>
              )}

              {/* باقي الأقسام FOOD و PHARMACY تعمل بنفس المنطق الديناميكي */}
            </>
          ) : (
            <div className="space-y-12">
               {/* تتبع الطلب النشط */}
               <div className="animate-in zoom-in space-y-8 text-center">
                  <div className="bg-white p-12 rounded-full shadow-2xl inline-block border-4 border-emerald-50">
                     <Timer className="h-16 w-16 text-emerald-600 animate-pulse" />
                  </div>
                  <h2 className="text-2xl font-black">جاري تنفيذ طلبك...</h2>
               </div>
