       {isDistOpen && (
          <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-end md:items-center justify-center p-4">
             <div className="bg-white w-full max-w-md rounded-t-[2.5rem] md:rounded-[3.5rem] p-8 md:p-10 space-y-6 md:space-y-8 animate-in slide-in-from-bottom md:zoom-in duration-300">
                <div className="flex justify-between items-center px-2">
                   <button onClick={() => setIsDistOpen(false)} className="p-3 bg-slate-50 text-slate-400 rounded-2xl hover:text-rose-500 transition-all"><X /></button>
                   <div className="text-right">
                      <h3 className="text-xl md:text-2xl font-black text-slate-900">مراكز المنوفية</h3>
                   </div>
                </div>
                <div className="grid grid-cols-2 gap-3 md:gap-4">
                   {districts.map(d => (
                     <button key={d.id} onClick={() => { onDistrictSelect(d); setIsDistOpen(false); }} className={`p-4 md:p-5 rounded-[1.5rem] md:rounded-[2rem] font-black text-xs md:text-sm transition-all border-2 ${selectedDistrict?.id === d.id ? 'bg-emerald-600 text-white border-emerald-500 shadow-xl' : 'bg-slate-50 text-slate-600 border-transparent hover:bg-slate-100'}`}>
                        {d.name}
                     </button>
                   ))}
                </div>
             </div>
          </div>
       )}

       {isVillOpen && (
          <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-end md:items-center justify-center p-4">
             <div className="bg-white w-full max-w-md rounded-t-[2.5rem] md:rounded-[3.5rem] p-6 md:p-8 flex flex-col h-[75vh] md:h-auto md:max-h-[80vh] animate-in slide-in-from-bottom md:zoom-in duration-300 shadow-2xl">
                <div className="flex justify-between items-center mb-6 shrink-0 px-2">
                   <button onClick={() => setIsVillOpen(false)} className="p-3 bg-slate-50 text-slate-400 rounded-2xl"><X /></button>
                   <div className="text-right">
                      <h3 className="text-xl md:text-2xl font-black">قرى مركز {selectedDistrict?.name}</h3>
                   </div>
                </div>
                <div className="px-2 mb-4 shrink-0">
                   <input 
                     value={villSearch} 
                     onChange={e => setVillSearch(e.target.value)} 
                     placeholder="ابحث عن اسم القرية..." 
                     className="w-full bg-slate-50 rounded-2xl p-4 text-xs font-black outline-none border-2 border-slate-100 focus:border-emerald-500 text-right"
                   />
                </div>
                <div className="flex-1 overflow-y-auto no-scrollbar space-y-2 px-2">
                   {selectedDistrict?.villages.filter(v => v.name.includes(villSearch)).map(v => (
                     <button key={v.id} onClick={() => { onVillageSelect(v); setIsVillOpen(false); setVillSearch(''); }} className={`w-full p-5 md:p-6 rounded-[1.5rem] md:rounded-[2.2rem] font-black text-sm md:text-md text-right flex items-center justify-between flex-row-reverse transition-all border-2 ${selectedVillage?.id === v.id ? 'bg-emerald-50 text-emerald-600 border-emerald-200 shadow-sm' : 'bg-slate-50 text-slate-600 border-transparent hover:bg-white hover:shadow-md'}`}>
                        {v.name}
                        {selectedVillage?.id === v.id && <Check className="h-5 w-5" />}
