  const [isVillOpen, setIsVillOpen] = useState(false);
  const [villSearch, setVillSearch] = useState('');

  return (
    <div className="space-y-4 bg-white p-5 md:p-6 rounded-[2.5rem] md:rounded-[3.5rem] border border-slate-100 shadow-xl shadow-slate-100/50 animate-reveal">
       <div className="flex items-center gap-4 flex-row-reverse text-right mb-2">
          <div className={`${iconBg} p-2.5 md:p-3 rounded-xl md:rounded-2xl text-white shadow-lg`}>
             {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement<any>, { className: "h-5 w-5" }) : icon}
          </div>
          <div className="flex flex-col">
             <label className="text-sm md:text-md font-black text-slate-900">{label}</label>
             <span className="text-[9px] md:text-[10px] font-bold text-slate-400">{helper}</span>
