       <div className="relative">
          <div className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300"><Edit3 className="h-4 w-4" /></div>
          <input value={notes} onChange={e => onNotesChange(e.target.value)} placeholder="وصف دقيق للعنوان (الشارع، المحل...)" className="w-full bg-slate-50 rounded-[1.5rem] md:rounded-3xl py-4 md:py-5 pr-14 pl-6 text-[10px] md:text-xs font-bold outline-none border-2 border-transparent focus:border-emerald-500 text-right transition-all shadow-inner" />
       </div>

       {isDistOpen && (
          <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-end md:items-center justify-center p-4 animate-in fade-in">
             <div className="bg-white w-full max-w-md rounded-t-[2.5rem] md:rounded-[3.5rem] p-8 md:p-10 space-y-6 md:space-y-8 animate-in slide-in-from-bottom duration-300">
                <div className="flex justify-between items-center px-2">
                   <button onClick={() => setIsDistOpen(false)} className="p-3 bg-slate-50 text-slate-400 rounded-2xl"><X /></button>
                   <h3 className="text-xl md:text-2xl font-black text-slate-900 text-right">مراكز المنوفية</h3>
                </div>
                <div className="grid grid-cols-2 gap-3 md:gap-4">
                   {districts.map(d => (
                     <button key={d.id} onClick={() => { onDistrictSelect(d); setIsDistOpen(false); }} className={`p-4 md:p-5 rounded-[1.5rem] md:rounded-[2rem] font-black text-xs md:text-sm transition-all border-2 ${selectedDistrict?.id === d.id ? 'bg-emerald-600 text-white border-emerald-500 shadow-xl' : 'bg-slate-50 text-slate-600 border-transparent'}`}>{d.name}</button>
                   ))}
                </div>
             </div>
          </div>
       )}

       {isVillOpen && (
          <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-end md:items-center justify-center p-4 animate-in fade-in">
             <div className="bg-white w-full max-w-md rounded-t-[2.5rem] md:rounded-[3.5rem] p-6 md:p-8 flex flex-col h-[75vh] md:h-auto md:max-h-[80vh] animate-in slide-in-from-bottom duration-300">
                <div className="flex justify-between items-center mb-6 shrink-0 px-2">
                   <button onClick={() => setIsVillOpen(false)} className="p-3 bg-slate-50 text-slate-400 rounded-2xl"><X /></button>
                   <h3 className="text-xl md:text-2xl font-black">قرى مركز {selectedDistrict?.name}</h3>
                </div>
                <div className="px-2 mb-4 shrink-0">
                   <input value={villSearch} onChange={e => setVillSearch(e.target.value)} placeholder="بحث عن اسم القرية..." className="w-full bg-slate-50 rounded-2xl p-4 text-xs font-black outline-none border-2 border-slate-100 focus:border-emerald-500 text-right" />
                </div>
                <div className="flex-1 overflow-y-auto no-scrollbar space-y-2 px-2">
                   {selectedDistrict?.villages.filter(v => v.name.includes(villSearch)).map(v => (
                     <button key={v.id} onClick={() => { onVillageSelect(v); setIsVillOpen(false); setVillSearch(''); }} className={`w-full p-5 md:p-6 rounded-[1.5rem] md:rounded-[2.2rem] font-black text-sm text-right flex items-center justify-between flex-row-reverse transition-all border-2 ${selectedVillage?.id === v.id ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-slate-50 text-slate-600 border-transparent hover:bg-white'}`}>
                        {v.name} {selectedVillage?.id === v.id && <Check className="h-5 w-5" />}
                     </button>
                   ))}
                </div>
             </div>
          </div>
       )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [geoData, setGeoData] = useState<District[]>([]);
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [ads, setAds] = useState<Ad[]>([]);

  // TAXI States
  const [pickupDistrict, setPickupDistrict] = useState<District | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffDistrict, setDropoffDistrict] = useState<District | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [rideVehicleType, setRideVehicleType] = useState<VehicleType>('TOKTOK');
  const [aiRoadDistance, setAiRoadDistance] = useState<number | null>(null);
  const [isCalculatingAiDist, setIsCalculatingAiDist] = useState(false);

  // PHARMACY States
  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionImg, setPrescriptionImg] = useState<string | null>(null);

  // Active Order States
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);

  useEffect(() => {
    const unsubGeo = onSnapshot(collection(db, "geo_config"), (snap) => {
      setGeoData(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[]);
    });
    const unsubRest = onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    const unsubAds = onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });
    const unsubOrders = onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.sort((a, b) => b.createdAt - a.createdAt).find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubGeo(); unsubRest(); unsubAds(); unsubOrders(); };
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder?.id, activeOrder?.status]);

  // AI Distance Logic
  useEffect(() => {
    const fetchAiDistance = async () => {
      if (!pickupVillage || !dropoffVillage) { setAiRoadDistance(null); return; }
      if (pickupVillage.id === dropoffVillage.id) { setAiRoadDistance(2); return; }
      setIsCalculatingAiDist(true);
      try {
        const straightDist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `قدر المسافة الحقيقية للسيارات بين قرية "${pickupVillage.name}" و قرية "${dropoffVillage.name}" في محافظة المنوفية. المسافة الجوية هي ${straightDist.toFixed(1)} كم. أجب برقم المسافة فقط.`,
        });
        const dist = parseFloat(response.text?.trim() || '0');
        setAiRoadDistance(isNaN(dist) ? parseFloat((straightDist * 1.3).toFixed(1)) : dist);
      } catch (error) { setAiRoadDistance(calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng) * 1.3); }
      finally { setIsCalculatingAiDist(false); }
    };
    fetchAiDistance();
  }, [pickupVillage?.id, dropoffVillage?.id]);

  const approxRidePrice = useMemo(() => {
    if (!pickupVillage || !dropoffVillage) return 0;
    const dist = aiRoadDistance || calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
    const multipliers = DEFAULT_PRICING.multipliers as any;
    const multiplier = multipliers[rideVehicleType] || 1;
    if (pickupVillage.id === dropoffVillage.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multiplier), DEFAULT_PRICING.minPrice);
  }, [pickupVillage, dropoffVillage, rideVehicleType, aiRoadDistance]);

  const handleCreateRideOrder = async () => {
    if(!pickupVillage || !dropoffVillage) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'TAXI',
        pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        pickupNotes, dropoffNotes, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), 
        requestedVehicleType: rideVehicleType, price: approxRidePrice, distance: aiRoadDistance || 0,
        operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
    } catch(e) { alert('حدث خطأ'); } finally { setIsSubmitting(false); }
  };

  const handlePharmacyOrder = async () => {
    if(!dropoffVillage) return alert('اختر مكان التوصيل');
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'PHARMACY',
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        dropoffNotes, notes: pharmacyNotes, prescriptionImage: prescriptionImg,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: 25, distance: 0, operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
    } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => setPrescriptionImg(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        driverPhoto: offer.driverPhoto || null, status: OrderStatus.ACCEPTED, acceptedAt: Date.now(),
        price: offer.price
      });
    } catch (e) { alert('فشل قبول العرض'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      <div className="rh-ui-panel no-scrollbar z-[100] bg-slate-50 overflow-y-auto h-full">
        <div className="p-5 md:p-12 space-y-8 pb-32 max-w-2xl mx-auto text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div className="text-right">
                    <h2 className="text-3xl font-black text-slate-950 tracking-tighter">وصـــلــهــا المنوفية</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase mt-1">تطبيقك الأول للتوصيل والطلبات</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-[1.8rem] shadow-sm"><Bot /></button>
              </div>

              {ads.length > 0 && (
                <div className="flex gap-4 overflow-x-auto no-scrollbar py-2">
                   {ads.filter(ad => ad.isActive).map(ad => (
                     <div key={ad.id} className="min-w-[85%] aspect-video bg-slate-900 rounded-[2.5rem] overflow-hidden relative shadow-xl">
                        <img src={ad.imageUrl} className="w-full h-full object-cover opacity-80" />
                        <div className="absolute inset-0 bg-gradient-to-t from-slate-950/80 flex flex-col justify-end p-6">
                           <h4 className="text-white font-black text-lg">{ad.title}</h4>
                        </div>
                     </div>
                   ))}
                </div>
              )}

              <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'طعام', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-6 rounded-[2.2rem] flex flex-col items-center gap-2 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-xl' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as any, { className: "h-7 w-7" }) : cat.icon}
                       <span className="text-[11px] font-black">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'TAXI' && (
                <div className="space-y-6">
                   <LocationSelector districts={geoData} label="نقطة الانطلاق" helper="موقعك الحالي" icon={<MapPin />} iconBg="bg-emerald-500" selectedDistrict={pickupDistrict} selectedVillage={pickupVillage} notes={pickupNotes} onDistrictSelect={setPickupDistrict} onVillageSelect={setPickupVillage} onNotesChange={setPickupNotes} />
                   <LocationSelector districts={geoData} label="وجهة الوصول" helper="إلى أين نذهب؟" icon={<Check />} iconBg="bg-rose-500" selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes} onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes} />

                   <div className="grid grid-cols-3 gap-3">
                      {['TOKTOK', 'MOTORCYCLE', 'CAR'].map(v => (
                        <button key={v} onClick={() => setRideVehicleType(v as any)} className={`py-4 rounded-2xl font-black text-[10px] border-2 transition-all ${rideVehicleType === v ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-md' : 'bg-white border-slate-100 text-slate-300'}`}>{v}</button>
                      ))}
                   </div>

                   <div className="bg-slate-950 p-8 rounded-[3rem] text-white space-y-6">
                      <div className="text-center space-y-1">
                        <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">التكلفة التقريبية الذكية</p>
                        <h3 className="text-5xl font-black">{isCalculatingAiDist ? '...' : approxRidePrice} <span className="text-xs opacity-40">ج.م</span></h3>
                      </div>
                      <button onClick={handleCreateRideOrder} disabled={isSubmitting || !pickupVillage || !dropoffVillage} className="w-full bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-xl shadow-2xl active:scale-95 transition-all">اطلب مشوارك الآن</button>
                   </div>
                </div>
              )}

              {selectedCategory === 'FOOD' && (
                <div className="space-y-6 animate-reveal">
                   <LocationSelector districts={geoData} label="مكان التوصيل" helper="أين ستستلم طلبك؟" icon={<MapPin />} iconBg="bg-rose-500" selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes} onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes} />
                   <div className="grid grid-cols-1 gap-4">
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-6 rounded-[3rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group">
                           <div className="flex items-center gap-4 flex-row-reverse text-right">
                              <div className="w-16 h-16 bg-slate-100 rounded-3xl overflow-hidden shadow-inner shrink-0">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-4 text-slate-200" />}
                              </div>
                              <div>
                                 <h4 className="font-black text-lg text-slate-800">{rest.name}</h4>
                                 <p className="text-[10px] font-bold text-slate-400">{rest.category}</p>
                              </div>
                           </div>
                           <ChevronLeft className="h-5 w-5 text-slate-300 group-hover:text-emerald-500 transition-colors" />
                        </div>
                      ))}
                   </div>
                </div>
              )}

              {selectedCategory === 'PHARMACY' && (
                <div className="space-y-6 animate-reveal">
                   <LocationSelector districts={geoData} label="مكان التوصيل" helper="عنوانك لاستلام الأدوية" icon={<MapPin />} iconBg="bg-rose-500" selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage} notes={dropoffNotes} onDistrictSelect={setDropoffDistrict} onVillageSelect={setDropoffVillage} onNotesChange={setDropoffNotes} />
                   <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
                      <div className="space-y-2">
                        <label className="text-xs font-black text-slate-400 px-2 block">اكتب طلبك أو اسم العلاج</label>
                        <textarea value={pharmacyNotes} onChange={e => setPharmacyNotes(e.target.value)} placeholder="مثال: علبة بنادول أزرق، علبة خافض حرارة للأطفال..." className="w-full bg-slate-50 border-none rounded-[1.5rem] p-5 text-sm font-bold outline-none text-right shadow-inner min-h-[120px]" />
                      </div>
                      <div className="flex items-center gap-4">
                         <div className="flex-1 space-y-2">
                            <label className="text-[10px] font-black text-slate-400 px-2 block">ارفع صورة الروشتة (اختياري)</label>
                            <input type="file" id="prescription" className="hidden" accept="image/*" onChange={handleImageUpload} />
                            <label htmlFor="prescription" className="w-full bg-emerald-50 border-2 border-dashed border-emerald-200 py-4 rounded-2xl flex items-center justify-center gap-3 cursor-pointer text-emerald-600 font-black text-xs">
                               <Camera className="h-5 w-5" /> {prescriptionImg ? 'تم رفع الصورة' : 'اضغط للتصوير'}
                            </label>
                         </div>
                         {prescriptionImg && (
                           <div className="w-20 h-20 rounded-2xl overflow-hidden border-4 border-white shadow-lg shrink-0">
                              <img src={prescriptionImg} className="w-full h-full object-cover" />
                           </div>
                         )}
                      </div>
                      <button onClick={handlePharmacyOrder} disabled={isSubmitting || !dropoffVillage} className="w-full bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-lg shadow-xl active:scale-95 transition-all">إرسال طلب الصيدلية</button>
                   </div>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-10 animate-in fade-in py-10">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="text-center space-y-10">
                    <div className="relative inline-block py-8">
                       <div className="bg-white p-12 rounded-full shadow-2xl relative z-10 animate-glow">
                          <Navigation2 className="h-20 w-20 text-emerald-600 animate-pulse" />
                       </div>
                       <div className="absolute inset-0 bg-emerald-500/10 blur-[100px] rounded-full scale-150"></div>
                    </div>
                    <div>
                       <h2 className="text-3xl font-black text-slate-950 tracking-tighter">جاري البحث عن كابتن...</h2>
                       <p className="text-slate-400 font-bold text-sm mt-2">ستظهر عروض الأسعار هنا فوراً</p>
                    </div>
                    <div className="space-y-4 px-2">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-xl flex justify-between items-center animate-reveal">
                            <div className="text-center space-y-2">
                               <p className="text-3xl font-black text-emerald-700">{offer.price} <span className="text-xs opacity-40">ج.م</span></p>
                               <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-8 py-2 rounded-xl font-black text-xs shadow-lg active:scale-90">قبول</button>
                            </div>
                            <div className="flex items-center gap-4 flex-row-reverse text-right">
                               <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center overflow-hidden border-2 border-white shadow-md">
                                 {offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="text-emerald-400 h-8 w-8" />}
                               </div>
                               <div>
                                  <p className="font-black text-slate-900">{offer.driverName}</p>
                                  <div className="flex items-center gap-1.5 text-amber-500 font-black text-[10px] mt-1 bg-amber-50 px-2 py-0.5 rounded-full w-fit mr-auto"><Star className="h-3 w-3 fill-amber-400" /> {offer.driverRating}</div>
                               </div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-xs uppercase tracking-[0.3em] py-4 hover:underline">إلغاء الطلب</button>
                 </div>
               ) : activeOrder.status === OrderStatus.DELIVERED ? (
                 <div className="bg-white p-10 rounded-[4rem] shadow-2xl text-center space-y-8 animate-in zoom-in border-4 border-emerald-500/10">
                    <PartyPopper className="h-20 w-20 text-emerald-500 mx-auto animate-bounce" />
                    <h2 className="text-3xl font-black text-slate-950">وصلت بالسلامة!</h2>
                    <p className="text-sm font-bold text-slate-400">تقييمك يساعدنا على تحسين جودة "وصـــلــهــا"</p>
                    <div className="bg-slate-50 p-8 rounded-[3rem] space-y-6">
                       <div className="flex justify-center gap-3">
                          {[1,2,3,4,5].map(s => (
                            <button key={s} onClick={() => setRating(s)} className="transition-all active:scale-75"><Star className={`h-12 w-12 ${rating >= s ? 'fill-amber-400 text-amber-400' : 'text-slate-200'}`} /></button>
                          ))}
                       </div>
                       <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="اكتب رأيك هنا..." className="w-full bg-white border-2 border-slate-100 rounded-[2rem] p-6 font-bold text-sm outline-none text-right shadow-inner" />
                    </div>
                    <button onClick={async () => {
                      await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.DELIVERED_RATED, rating, feedback: feedback.trim(), ratedAt: Date.now() });
