const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showFullMenu, setShowFullMenu] = useState(false);
  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
      {showFullMenu && restaurant.menuImageURL && <HighResMenuViewer url={restaurant.menuImageURL} onClose={() => setShowFullMenu(false)} />}

      <div className="bg-slate-900 p-6 pt-14 text-white flex justify-between items-center shadow-xl shrink-0">
        <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl active:scale-90"><ArrowRight className="h-6 w-6" /></button>
        <div className="text-right">
          <h3 className="text-xl font-black">{restaurant.name}</h3>
          <p className="text-[10px] font-bold text-emerald-400">{restaurant.category}</p>
        </div>
      </div>
      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 no-scrollbar pb-32">
        {restaurant.menuImageURL && (
          <button onClick={() => setShowFullMenu(true)} className="w-full bg-emerald-600 p-5 rounded-[2rem] text-white flex justify-between items-center shadow-xl mb-4 active:scale-95 transition-all">
            <div className="bg-white/20 p-3 rounded-xl"><ZoomIn className="h-5 w-5" /></div>
            <div className="text-right">
               <h4 className="font-black">تصفح المنيو الورقي</h4>
               <p className="text-[9px] opacity-80 uppercase font-bold">عرض الصورة كاملة والتحميل</p>
            </div>
          </button>
        )}
        <div className="grid grid-cols-1 gap-3">
          {restaurant.menu?.map(item => (
            <div key={item.id} className="bg-white p-4 rounded-[2rem] shadow-sm border border-slate-100 flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-xl">
                  <button onClick={() => addToCart(item)} className="p-1.5 bg-emerald-500 text-white rounded-lg active:scale-75"><Plus className="h-4 w-4" /></button>
                  <span className="font-black text-sm w-4 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                  <button onClick={() => removeFromCart(item.id)} className="p-1.5 bg-rose-50 text-rose-500 rounded-lg active:scale-75"><Minus className="h-4 w-4" /></button>
                </div>
                <p className="font-black text-emerald-600 text-xs">{item.price} ج.م</p>
              </div>
              <div className="text-right flex items-center gap-3 flex-row-reverse overflow-hidden">
                <div className="w-12 h-12 bg-slate-100 rounded-xl overflow-hidden shrink-0">
                  {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-3 text-slate-200" />}
                </div>
                <p className="font-black text-slate-800 text-sm truncate">{item.name}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
      {cart.length > 0 && (
        <div className="fixed bottom-0 left-0 right-0 p-6 bg-white border-t border-slate-100 pb-12 shadow-[0_-20px_50px_rgba(0,0,0,0.1)] z-[1200]">
          <div className="flex justify-between items-center mb-4">
            <p className="text-2xl font-black text-slate-900">{total} ج.م</p>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">إجمالي الطلب</p>
          </div>
          <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-6 rounded-[2rem] font-black text-lg shadow-xl flex items-center justify-center gap-3 active:scale-95">تأكيد الطلب</button>
        </div>
      )}
    </div>
  );
};

