          <div onClick={() => selectedDistrict ? setIsVillOpen(true) : alert('اختر المركز أولاً')} className={`p-4 rounded-[1.5rem] flex items-center justify-between cursor-pointer border-2 border-transparent transition-all ${selectedDistrict ? 'bg-slate-50 active:border-emerald-500' : 'bg-slate-100 opacity-50'}`}>
             <ChevronDown className="h-4 w-4 text-slate-300" />
             <div className="text-right truncate flex-1 px-1">
                <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">القرية</p>
                <p className="text-[10px] font-black text-slate-800 truncate">{selectedVillage?.name || 'اختر'}</p>
             </div>
          </div>
       </div>
       <div className="relative">
          <input value={notes} onChange={e => onNotesChange(e.target.value)} placeholder="وصف دقيق للعنوان (الشارع، رقم البيت...)" className="w-full bg-slate-50 rounded-[1.5rem] py-4 pr-12 pl-6 text-[11px] font-bold outline-none border-2 border-transparent focus:border-emerald-500 text-right transition-all" />
          <Edit3 className="absolute right-5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
       </div>

       {isDistOpen && (
          <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-end justify-center p-4">
             <div className="bg-white w-full max-w-md rounded-t-[2.5rem] p-8 space-y-6 animate-in slide-in-from-bottom duration-300">
                <div className="flex justify-between items-center"><button onClick={() => setIsDistOpen(false)} className="p-3 bg-slate-50 text-slate-400 rounded-2xl"><X /></button><h3 className="text-xl font-black">مراكز المنوفية</h3></div>
                <div className="grid grid-cols-2 gap-3 max-h-[50vh] overflow-y-auto no-scrollbar">
                   {districts.map(d => <button key={d.id} onClick={() => { onDistrictSelect(d); setIsDistOpen(false); }} className={`p-4 rounded-2xl font-black text-xs transition-all border-2 ${selectedDistrict?.id === d.id ? 'bg-emerald-600 text-white border-emerald-500' : 'bg-slate-50 text-slate-600 border-transparent'}`}>{d.name}</button>)}
                </div>
             </div>
          </div>
       )}
       {isVillOpen && (
          <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-end justify-center p-4">
             <div className="bg-white w-full max-w-md rounded-t-[2.5rem] p-6 flex flex-col h-[75vh] animate-in slide-in-from-bottom duration-300">
                <div className="flex justify-between items-center mb-6"><button onClick={() => setIsVillOpen(false)} className="p-3 bg-slate-50 text-slate-400 rounded-2xl"><X /></button><h3 className="text-xl font-black">قرى مركز {selectedDistrict?.name}</h3></div>
                <div className="px-2 mb-4"><input value={villSearch} onChange={e => setVillSearch(e.target.value)} placeholder="بحث عن قرية..." className="w-full bg-slate-50 rounded-2xl p-4 text-xs font-black outline-none border-2 border-slate-100 focus:border-emerald-500 text-right" /></div>
                <div className="flex-1 overflow-y-auto no-scrollbar space-y-2 px-2 pb-10">
                   {selectedDistrict?.villages.filter(v => v.name.includes(villSearch)).map(v => (
                     <button key={v.id} onClick={() => { onVillageSelect(v); setIsVillOpen(false); setVillSearch(''); }} className={`w-full p-5 rounded-[1.8rem] font-black text-sm text-right flex items-center justify-between flex-row-reverse transition-all border-2 ${selectedVillage?.id === v.id ? 'bg-emerald-50 text-emerald-600 border-emerald-200 shadow-sm' : 'bg-slate-50 text-slate-600 border-transparent'}`}>
                        {v.name} {selectedVillage?.id === v.id && <Check className="h-5 w-5" />}
                     </button>
                   ))}
                </div>
             </div>
          </div>
       )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [geoData, setGeoData] = useState<District[]>([]);
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [ads, setAds] = useState<Ad[]>([]);

  // Order creation states
  const [pickupDist, setPickupDist] = useState<District | null>(null);
  const [pickupVill, setPickupVill] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffDist, setDropoffDist] = useState<District | null>(null);
  const [dropoffVill, setDropoffVill] = useState<Village | null>(null);
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [rideVehicle, setRideVehicle] = useState<VehicleType>('TOKTOK');
  const [aiRoadDistance, setAiRoadDistance] = useState<number | null>(null);
  const [isCalculatingAi, setIsCalculatingAi] = useState(false);
  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionImg, setPrescriptionImg] = useState<string | null>(null);

  // Active order states
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [viewingRest, setViewingRest] = useState<Restaurant | null>(null);
  const [expandedAd, setExpandedAd] = useState<Ad | null>(null);

  useEffect(() => {
    const unsubGeo = onSnapshot(collection(db, "geo_config"), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[];
      setGeoData(data);
    });
    const unsubRest = onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    const unsubAds = onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });
    const unsubOrders = onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.sort((a, b) => b.createdAt - a.createdAt).find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubGeo(); unsubRest(); unsubAds(); unsubOrders(); };
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder?.id, activeOrder?.status]);

  useEffect(() => {
    const fetchAiDist = async () => {
      if (!pickupVill || !dropoffVill) { setAiRoadDistance(null); return; }
      if (pickupVill.id === dropoffVill.id) { setAiRoadDistance(2); return; }
      setIsCalculatingAi(true);
      try {
        const straight = calculateDistance(pickupVill.center.lat, pickupVill.center.lng, dropoffVill.center.lat, dropoffVill.center.lng);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const resp = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `قدر المسافة الحقيقية للسيارات بين قرية "${pickupVill.name}" و قرية "${dropoffVill.name}" في المنوفية. المسافة الجوية هي ${straight.toFixed(1)} كم. أجب برقم المسافة فقط بالكيلومتر.`,
        });
        const dist = parseFloat(resp.text?.trim() || '0');
        setAiRoadDistance(isNaN(dist) ? parseFloat((straight * 1.3).toFixed(1)) : dist);
      } catch { setAiRoadDistance(calculateDistance(pickupVill.center.lat, pickupVill.center.lng, dropoffVill.center.lat, dropoffVill.center.lng) * 1.3); }
      finally { setIsCalculatingAi(false); }
    };
    fetchAiDist();
  }, [pickupVill?.id, dropoffVill?.id]);

  const approxRidePrice = useMemo(() => {
    if (!pickupVill || !dropoffVill) return 0;
    const dist = aiRoadDistance || calculateDistance(pickupVill.center.lat, pickupVill.center.lng, dropoffVill.center.lat, dropoffVill.center.lng);
    const multi = (DEFAULT_PRICING.multipliers as any)[rideVehicle] || 1;
    if (pickupVill.id === dropoffVill.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multi), DEFAULT_PRICING.minPrice);
  }, [pickupVill, dropoffVill, rideVehicle, aiRoadDistance]);

  const handleCreateRideOrder = async () => {
    if(!pickupVill || !dropoffVill) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'TAXI',
        pickup: { address: pickupVill.name, lat: pickupVill.center.lat, lng: pickupVill.center.lng, villageName: pickupVill.name },
        dropoff: { address: dropoffVill.name, lat: dropoffVill.center.lat, lng: dropoffVill.center.lng, villageName: dropoffVill.name },
        pickupNotes, dropoffNotes, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), 
        requestedVehicleType: rideVehicle, price: approxRidePrice, distance: aiRoadDistance || 0,
        operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
    } catch { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRest || !dropoffVill) return alert('يرجى اختيار مكان التوصيل أولاً');
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(viewingRest.lat, viewingRest.lng, dropoffVill.center.lat, dropoffVill.center.lng);
      const delivery = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodSum = cart.reduce((acc, c) => acc + (c.price * c.quantity), 0);
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRest.name, lat: viewingRest.lat, lng: viewingRest.lng, villageName: viewingRest.address },
        dropoff: { address: dropoffVill.name, lat: dropoffVill.center.lat, lng: dropoffVill.center.lng, villageName: dropoffVill.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: delivery + foodSum, distance: dist, foodItems: cart, restaurantId: viewingRest.id, restaurantName: viewingRest.name,
        pickupNotes: `طلب طعام من ${viewingRest.name}`, dropoffNotes, operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
      setViewingRest(null);
    } catch { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handlePharmacyOrder = async () => {
    if(!dropoffVill) return alert('يرجى اختيار مكان التوصيل');
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'PHARMACY',
        dropoff: { address: dropoffVill.name, lat: dropoffVill.center.lat, lng: dropoffVill.center.lng, villageName: dropoffVill.name },
        dropoffNotes, notes: pharmacyNotes, prescriptionImage: prescriptionImg,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: 25, distance: 0, operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
      setPharmacyNotes(''); setPrescriptionImg(null);
    } catch { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRest && <RestaurantMenu restaurant={viewingRest} onClose={() => setViewingRest(null)} onCheckout={handleCheckoutFood} />}
      {expandedAd && <AdDetailModal ad={expandedAd} onClose={() => setExpandedAd(null)} onAction={(ad) => {
         if (ad.type === 'restaurant' && ad.targetId) {
            const r = restaurants.find(res => res.id === ad.targetId);
            if (r) setViewingRest(r);
         } else { window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent('أريد الاستفسار عن: ' + ad.title)}`); }
      }} />}

      <div className="rh-ui-panel no-scrollbar z-[100] bg-slate-50 overflow-y-auto h-full">
        <div className="p-5 md:p-12 space-y-8 pb-32 max-w-2xl mx-auto text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div className="text-right">
                    <h2 className="text-3xl font-black text-slate-950 tracking-tighter">وصـــلــهــا المنوفية</h2>
                    <p className="text-slate-400 font-bold text-[10px] uppercase mt-1">تطبيقك الأول للتوصيل والطلبات</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-emerald-50 text-emerald-600 rounded-[2rem] shadow-sm active:scale-90 transition-all border-none"><Bot /></button>
              </div>

              {ads.length > 0 && (
                <div className="flex gap-4 overflow-x-auto no-scrollbar py-2 scroll-smooth">
                   {ads.filter(ad => ad.isActive).map(ad => (
                     <div key={ad.id} onClick={() => setExpandedAd(ad)} className="min-w-[85%] aspect-video bg-slate-900 rounded-[2.5rem] overflow-hidden relative shadow-xl active:scale-95 transition-all">
                        <img src={ad.imageUrl} className="w-full h-full object-cover opacity-80" />
                        <div className="absolute inset-0 bg-gradient-to-t from-slate-950/90 flex flex-col justify-end p-6">
                           <h4 className="text-white font-black text-lg">{ad.title}</h4>
                        </div>
                     </div>
                   ))}
                </div>
              )}

              <div className="grid grid-cols-3 gap-3">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'طعام', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-7 rounded-[2.5rem] flex flex-col items-center gap-2 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-60'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as any, { className: "h-7 w-7" }) : cat.icon}
                       <span className="text-[11px] font-black">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {selectedCategory === 'TAXI' && (
                <div className="space-y-6 animate-reveal">
                   <LocationSelector districts={geoData} label="نقطة الانطلاق" helper="موقعك الحالي" icon={<MapPin />} iconBg="bg-emerald-500" selectedDistrict={pickupDist} selectedVillage={pickupVill} notes={pickupNotes} onDistrictSelect={setPickupDist} onVillageSelect={setPickupVill} onNotesChange={setPickupNotes} />
                   <LocationSelector districts={geoData} label="وجهة الوصول" helper="إلى أين نذهب؟" icon={<Check />} iconBg="bg-rose-500" selectedDistrict={dropoffDist} selectedVillage={dropoffVill} notes={dropoffNotes} onDistrictSelect={setDropoffDist} onVillageSelect={setDropoffVill} onNotesChange={setDropoffNotes} />

                   <div className="grid grid-cols-3 gap-3">
                      {['TOKTOK', 'MOTORCYCLE', 'CAR'].map(v => (
                        <button key={v} onClick={() => setRideVehicle(v as any)} className={`py-4 rounded-2xl font-black text-[10px] border-2 transition-all ${rideVehicle === v ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-md' : 'bg-white border-slate-100 text-slate-300'}`}>{v}</button>
                      ))}
                   </div>

                   <div className="bg-slate-950 p-8 rounded-[3rem] text-white space-y-6">
                      <div className="text-center space-y-1">
                        <p className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">التكلفة التقريبية (AI)</p>
                        <h3 className="text-5xl font-black">{isCalculatingAi ? '...' : approxRidePrice} <span className="text-xs opacity-40">ج.م</span></h3>
                      </div>
                      <button onClick={handleCreateRideOrder} disabled={isSubmitting || !pickupVill || !dropoffVill} className="w-full bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-xl shadow-2xl active:scale-95 transition-all">اطلب مشوارك الآن</button>
                   </div>
                </div>
              )}

              {selectedCategory === 'FOOD' && (
                <div className="space-y-6 animate-reveal">
                   <LocationSelector districts={geoData} label="مكان التوصيل" helper="أين ستستلم طلبك؟" icon={<MapPin />} iconBg="bg-rose-500" selectedDistrict={dropoffDist} selectedVillage={dropoffVill} notes={dropoffNotes} onDistrictSelect={setDropoffDist} onVillageSelect={setDropoffVill} onNotesChange={setDropoffNotes} />
                   <div className="grid grid-cols-1 gap-4">
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRest(rest)} className="bg-white p-6 rounded-[3rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group">
                           <div className="flex items-center gap-4 flex-row-reverse text-right">
                              <div className="w-16 h-16 bg-slate-100 rounded-3xl overflow-hidden shadow-inner shrink-0">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-4 text-slate-200" />}
                              </div>
                              <div><h4 className="font-black text-lg text-slate-800">{rest.name}</h4><p className="text-[10px] font-bold text-slate-400">{rest.category}</p></div>
                           </div>
                           <ChevronLeft className="h-5 w-5 text-slate-300 group-hover:text-emerald-500 transition-colors" />
                        </div>
                      ))}
                   </div>
                </div>
              )}

              {selectedCategory === 'PHARMACY' && (
                <div className="space-y-6 animate-reveal">
                   <LocationSelector districts={geoData} label="مكان التوصيل" helper="عنوانك لاستلام الأدوية" icon={<MapPin />} iconBg="bg-rose-500" selectedDistrict={dropoffDist} selectedVillage={dropoffVill} notes={dropoffNotes} onDistrictSelect={setDropoffDist} onVillageSelect={setDropoffVill} onNotesChange={setDropoffNotes} />
                   <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl space-y-6">
                      <div className="space-y-2"><label className="text-xs font-black text-slate-400 px-2 block">اكتب طلبك أو اسم العلاج</label><textarea value={pharmacyNotes} onChange={e => setPharmacyNotes(e.target.value)} placeholder="مثال: علبة بنادول، خافض حرارة..." className="w-full bg-slate-50 border-none rounded-[1.5rem] p-5 text-sm font-bold outline-none text-right shadow-inner min-h-[120px]" /></div>
                      <div className="flex items-center gap-4">
                         <div className="flex-1 space-y-2">
                            <label className="text-[10px] font-black text-slate-400 px-2 block">صورة الروشتة (اختياري)</label>
                            <input type="file" id="pres" className="hidden" accept="image/*" onChange={e => { const f = e.target.files?.[0]; if(f) { const r = new FileReader(); r.onloadend = () => setPrescriptionImg(r.result as string); r.readAsDataURL(f); } }} />
                            <label htmlFor="pres" className="w-full bg-emerald-50 border-2 border-dashed border-emerald-200 py-4 rounded-2xl flex items-center justify-center gap-3 cursor-pointer text-emerald-600 font-black text-xs"><Camera className="h-5 w-5" /> {prescriptionImg ? 'تم الرفع' : 'اضغط للتصوير'}</label>
                         </div>
                         {prescriptionImg && <div className="w-20 h-20 rounded-2xl overflow-hidden border-4 border-white shadow-lg shrink-0"><img src={prescriptionImg} className="w-full h-full object-cover" /></div>}
                      </div>
                      <button onClick={handlePharmacyOrder} disabled={isSubmitting || !dropoffVill} className="w-full bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-lg shadow-xl active:scale-95 transition-all">إرسال طلب الصيدلية</button>
                   </div>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-10 animate-in fade-in py-10">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="text-center space-y-10">
                    <div className="relative inline-block py-8"><div className="bg-white p-12 rounded-full shadow-2xl relative z-10 animate-glow"><Navigation2 className="h-20 w-20 text-emerald-600 animate-pulse" /></div><div className="absolute inset-0 bg-emerald-500/10 blur-[100px] rounded-full scale-150"></div></div>
                    <div><h2 className="text-3xl font-black text-slate-950 tracking-tighter">جاري البحث عن كابتن...</h2><p className="text-slate-400 font-bold text-sm mt-2">ستظهر عروض الأسعار هنا فوراً</p></div>
                    <div className="space-y-4 px-2">
                       {incomingOffers.map(off => (
                         <div key={off.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-xl flex justify-between items-center animate-reveal">
                            <div className="text-center space-y-2">
                               <p className="text-3xl font-black text-emerald-700">{off.price} <span className="text-xs opacity-40">ج.م</span></p>
                               <button onClick={() => { updateDoc(doc(db, "orders", activeOrder.id), { driverId: off.driverId, driverName: off.driverName, driverPhone: off.driverPhone, status: OrderStatus.ACCEPTED, acceptedAt: Date.now(), price: off.price }); }} className="bg-emerald-600 text-white px-8 py-2 rounded-xl font-black text-xs shadow-lg active:scale-90">قبول</button>
                            </div>
                            <div className="flex items-center gap-4 flex-row-reverse text-right">
                               <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center overflow-hidden border-2 border-white shadow-md">
                                 {off.driverPhoto ? <img src={off.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="text-emerald-400 h-8 w-8" />}
                               </div>
                               <div><p className="font-black text-slate-900">{off.driverName}</p><div className="flex items-center gap-1.5 text-amber-500 font-black text-[10px] mt-1 bg-amber-50 px-2 py-0.5 rounded-full w-fit mr-auto"><Star className="h-3 w-3 fill-amber-400" /> {off.driverRating}</div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-xs uppercase tracking-[0.3em] py-4 hover:underline">إلغاء الطلب</button>
