      const foodSum = cart.reduce((acc, c) => acc + (c.price * c.quantity), 0);
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRest.name, lat: viewingRest.lat, lng: viewingRest.lng, villageName: viewingRest.address },
