import { db } from '../services/firebase';
import { 
  collection, doc, onSnapshot, setDoc, 
  updateDoc, arrayUnion, arrayRemove, getDoc, writeBatch
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  ArrowRight, MapPin, Plus, X, Trash2, 
  Loader2, Save, Map as MapIcon, Building2,
  Zap, PlusCircle, Globe, ChevronDown, Check, RefreshCw, AlertTriangle
} from 'lucide-react';

const AdminGeographyManager: React.FC<{ user: User }> = ({ user }) => {
  const navigate = useNavigate();
  const [districts, setDistricts] = useState<District[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDistId, setSelectedDistId] = useState<string | null>(null);
  const [newVillName, setNewVillName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isResetting, setIsResetting] = useState(false);

  useEffect(() => {
    const unsub = onSnapshot(collection(db, "geo_config"), (snap) => {
      if (!snap.empty) {
        setDistricts(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[]);
        setLoading(false);
      } else {
        setLoading(false);
      }
    });
    return () => unsub();
  }, []);

  const handleForceReset = async () => {
    if (!confirm('هل تريد مسح الإعدادات الحالية وتحديث الخريطة بكامل القرى الجديدة من النظام؟ سيتم إضافة كافة القرى التي زودتنا بها.')) return;
    setIsResetting(true);
    try {
      const batch = writeBatch(db);
      for (const dist of INITIAL_DATA) {
        const distRef = doc(db, "geo_config", dist.id);
        batch.set(distRef, dist);
      }
      await batch.commit();
      alert('تم تحديث كافة القرى بنجاح في قاعدة البيانات!');
    } catch (e) {
      alert('خطأ في التحديث');
    } finally {
      setIsResetting(false);
    }
  };

  const handleAddVillage = async () => {
    if (!selectedDistId || !newVillName.trim()) return;
    setIsSubmitting(true);
    try {
      const newVill: Village = {
        id: `v_${Date.now()}`,
        name: newVillName.trim(),
        center: { lat: 30.556, lng: 31.008 }
      };
      await updateDoc(doc(db, "geo_config", selectedDistId), {
        villages: arrayUnion(newVill)
      });
      setNewVillName('');
      alert('تم إضافة القرية بنجاح');
    } catch (e) {
      alert('خطأ في الإضافة');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRemoveVillage = async (distId: string, village: Village) => {
    if (!confirm(`حذف قرية "${village.name}"؟`)) return;
    try {
      await updateDoc(doc(db, "geo_config", distId), {
        villages: arrayRemove(village)
      });
    } catch (e) { alert('خطأ في الحذف'); }
  };

  return (
    <div className="max-w-6xl mx-auto p-6 md:p-10 space-y-10 animate-in slide-in-from-bottom duration-500 text-right pb-32" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
        <div className="flex items-center gap-5">
           <div className="bg-rose-500 p-4 rounded-3xl text-white shadow-xl">
              <MapIcon className="h-8 w-8" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tighter">نطاق المنوفية الجغرافي</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">إدارة المراكز والقرى المتاحة للتوصيل</p>
           </div>
        </div>
        <div className="flex gap-3">
           <button 
             onClick={handleForceReset}
             disabled={isResetting}
             className="bg-amber-500 text-white px-6 py-4 rounded-2xl font-black text-[10px] flex items-center gap-2 shadow-xl active:scale-95 transition-all"
           >
              {isResetting ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
              تحديث ومزامنة كافة القرى
           </button>
           <button onClick={() => navigate('/')} className="p-4 bg-white border border-slate-100 rounded-2xl shadow-sm text-slate-400 hover:text-rose-500 flex items-center gap-2">
             <ArrowRight className="h-5 w-5" />
           </button>
        </div>
      </div>

      {!loading && districts.length === 0 && (
         <div className="bg-amber-50 p-10 rounded-[3rem] border-2 border-amber-100 text-center space-y-4">
            <AlertTriangle className="h-12 w-12 text-amber-500 mx-auto" />
            <h3 className="text-xl font-black text-amber-900">لا توجد بيانات جغرافية!</h3>
            <p className="text-sm font-bold text-amber-700">يرجى الضغط على زر "تحديث ومزامنة كافة القرى" أعلاه لرفع القرى الافتراضية لقاعدة البيانات.</p>
         </div>
      )}

      {/* Add Village Form */}
      <div className="bg-slate-950 p-10 rounded-[4rem] shadow-2xl text-white relative overflow-hidden space-y-8">
         <div className="absolute top-0 left-0 w-64 h-full bg-rose-500/5 blur-3xl"></div>
         <div className="relative z-10">
            <h3 className="text-2xl font-black mb-2 flex items-center gap-3"><PlusCircle className="text-rose-400" /> إضافة قرية جديدة يدوياً</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-end mt-10">
               <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-4 block">المركز الإداري</label>
                  <select 
                    value={selectedDistId || ''} 
                    onChange={e => setSelectedDistId(e.target.value)}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl p-5 font-black text-sm outline-none appearance-none focus:border-rose-500"
                  >
                     <option value="" className="text-slate-900">اختر المركز...</option>
                     {districts.map(d => <option key={d.id} value={d.id} className="text-slate-900">{d.name}</option>)}
                  </select>
               </div>
               <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-4 block">اسم القرية</label>
                  <input 
                    value={newVillName}
                    onChange={e => setNewVillName(e.target.value)}
                    placeholder="اسم القرية/العزبة..."
                    className="w-full bg-white/5 border border-white/10 rounded-2xl p-5 font-black text-sm outline-none text-right focus:border-rose-500"
                  />
               </div>
               <button 
                 onClick={handleAddVillage}
                 disabled={isSubmitting || !selectedDistId || !newVillName}
                 className="bg-rose-500 hover:bg-rose-600 text-white py-5 rounded-2xl font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-20"
               >
                  {isSubmitting ? <Loader2 className="animate-spin h-5 w-5" /> : <><Save className="h-5 w-5" /> إضافة للمنظومة</>}
               </button>
            </div>
         </div>
      </div>

      {/* Districts List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
         {loading ? (
           <div className="col-span-full py-20 flex justify-center"><Loader2 className="h-12 w-12 animate-spin text-rose-500" /></div>
         ) : districts.sort((a,b) => a.name.localeCompare(b.name)).map(dist => (
           <div key={dist.id} className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-xl flex flex-col gap-6 group hover:border-rose-500 transition-all">
              <div className="flex items-center justify-between flex-row-reverse">
                 <div className="flex items-center gap-4 flex-row-reverse text-right">
                    <div className="bg-slate-50 p-4 rounded-2xl text-rose-500 group-hover:bg-rose-500 group-hover:text-white transition-all shadow-sm">
                       <Building2 className="h-6 w-6" />
                    </div>
                    <h4 className="font-black text-xl text-slate-900">{dist.name}</h4>
                 </div>
                 <span className="bg-rose-50 text-rose-600 px-4 py-1 rounded-full text-[10px] font-black">{dist.villages.length} قرية</span>
              </div>

              <div className="space-y-2 overflow-y-auto max-h-64 no-scrollbar border-r-4 border-slate-50 pr-4">
                 {dist.villages.map(v => (
                   <div key={v.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 transition-colors flex-row-reverse group/item">
                      <div className="flex items-center gap-3 flex-row-reverse">
                         <div className="w-1.5 h-1.5 rounded-full bg-rose-300"></div>
                         <p className="text-xs font-bold text-slate-600">{v.name}</p>
                      </div>
                      <button 
                        onClick={() => handleRemoveVillage(dist.id, v)}
                        className="p-2 text-rose-200 hover:text-rose-500 opacity-0 group-hover/item:opacity-100 transition-all"
                      >
                         <Trash2 className="h-4 w-4" />
                      </button>
                   </div>
                 ))}
              </div>
           </div>
         ))}
      </div>
    </div>
  );
};

export default AdminGeographyManager;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

// Types
import type { User, District, Village } from '../types';
import { MENOFIA_DATA as INITIAL_DATA } from '../config/constants';

// Services
import { db } from '../services/firebase';
import { 
  collection, doc, onSnapshot, setDoc, 
  updateDoc, arrayUnion, arrayRemove, writeBatch 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  ArrowRight, MapPin, Plus, X, Trash2, 
  Loader2, Save, Map as MapIcon, Building2,
  Zap, PlusCircle, RefreshCw, AlertTriangle, Search
} from 'lucide-react';

const AdminGeographyManager: React.FC<{ user: User }> = ({ user }) => {
  const navigate = useNavigate();
  const [districts, setDistricts] = useState<District[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedDistId, setSelectedDistId] = useState<string | null>(null);
  const [newVillName, setNewVillName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isResetting, setIsResetting] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const unsub = onSnapshot(collection(db, "geo_config"), (snap) => {
      if (!snap.empty) {
        setDistricts(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[]);
        setLoading(false);
      } else {
        setLoading(false);
      }
    });
    return () => unsub();
  }, []);

  const handleForceReset = async () => {
    if (!confirm('سيتم تحديث كافة القرى في قاعدة البيانات بالقائمة الشاملة الجديدة. هل تريد الاستمرار؟')) return;
    setIsResetting(true);
    try {
      const batch = writeBatch(db);
      for (const dist of INITIAL_DATA) {
        const distRef = doc(db, "geo_config", dist.id);
        batch.set(distRef, dist);
      }
      await batch.commit();
      alert('تمت المزامنة بنجاح!');
    } catch (e) {
      alert('فشل التحديث');
    } finally {
      setIsResetting(false);
    }
  };

  const handleAddVillage = async () => {
    if (!selectedDistId || !newVillName.trim()) return;
    setIsSubmitting(true);
    try {
      const newVill: Village = {
        id: `v_${Date.now()}`,
        name: newVillName.trim(),
        center: { lat: 30.556, lng: 31.008 }
      };
      await updateDoc(doc(db, "geo_config", selectedDistId), {
        villages: arrayUnion(newVill)
      });
      setNewVillName('');
      alert('تم الإضافة');
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleRemoveVillage = async (distId: string, village: Village) => {
    if (!confirm(`حذف قرية "${village.name}"؟`)) return;
    try {
      await updateDoc(doc(db, "geo_config", distId), {
        villages: arrayRemove(village)
      });
    } catch (e) { alert('خطأ'); }
  };

  return (
    <div className="max-w-6xl mx-auto p-6 md:p-10 space-y-10 animate-in slide-in-from-bottom duration-500 text-right pb-32" dir="rtl">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
        <div className="flex items-center gap-5">
           <div className="bg-rose-500 p-4 rounded-3xl text-white shadow-xl">
              <MapIcon className="h-8 w-8" />
           </div>
           <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tighter">خارطة المنوفية</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">إدارة {districts.reduce((a,b)=>a+b.villages.length, 0)} قرية مسجلة</p>
           </div>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
           <button 
             onClick={handleForceReset}
             disabled={isResetting}
             className="flex-1 md:flex-none bg-amber-500 text-white px-6 py-4 rounded-2xl font-black text-[10px] flex items-center justify-center gap-2 shadow-xl active:scale-95 transition-all"
           >
              {isResetting ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
              مزامنة القائمة الشاملة
           </button>
           <button onClick={() => navigate('/')} className="p-4 bg-white border border-slate-100 rounded-2xl shadow-sm text-slate-400 hover:text-rose-500 flex items-center gap-2">
             <ArrowRight className="h-5 w-5" />
           </button>
        </div>
      </div>

      {!loading && districts.length === 0 && (
         <div className="bg-amber-50 p-10 rounded-[3rem] border-2 border-amber-100 text-center space-y-4">
            <AlertTriangle className="h-12 w-12 text-amber-500 mx-auto" />
            <h3 className="text-xl font-black text-amber-900">الخريطة فارغة</h3>
            <p className="text-sm font-bold text-amber-700">اضغط على زر "مزامنة القائمة الشاملة" لرفع القرى المبرمجة.</p>
         </div>
      )}

      {/* Manual Entry */}
      <div className="bg-slate-950 p-8 rounded-[3.5rem] shadow-2xl text-white space-y-6 relative overflow-hidden">
         <div className="absolute top-0 right-0 w-64 h-full bg-rose-500/5 blur-3xl"></div>
         <h3 className="text-xl font-black flex items-center gap-3 relative z-10"><PlusCircle className="text-rose-400" /> إضافة قرية يدوياً</h3>
         <div className="grid grid-cols-1 md:grid-cols-3 gap-6 relative z-10">
            <div className="space-y-2">
               <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-4 block">المركز</label>
               <select value={selectedDistId || ''} onChange={e => setSelectedDistId(e.target.value)} className="w-full bg-white/5 border border-white/10 rounded-2xl p-5 font-black text-sm outline-none focus:border-rose-500">
                  <option value="" className="text-slate-900">اختر...</option>
                  {districts.map(d => <option key={d.id} value={d.id} className="text-slate-900">{d.name}</option>)}
               </select>
            </div>
            <div className="space-y-2">
               <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-4 block">اسم القرية</label>
               <input value={newVillName} onChange={e => setNewVillName(e.target.value)} placeholder="مثال: عزبة خليل" className="w-full bg-white/5 border border-white/10 rounded-2xl p-5 font-black text-sm outline-none text-right focus:border-rose-500" />
            </div>
            <button onClick={handleAddVillage} disabled={isSubmitting || !selectedDistId || !newVillName} className="bg-rose-500 text-white rounded-2xl font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-20 h-[62px] mt-auto">
               {isSubmitting ? <Loader2 className="animate-spin h-5 w-5" /> : <><Save className="h-5 w-5" /> حفظ</>}
            </button>
         </div>
      </div>

      {/* Global Search */}
      <div className="relative group">
         <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-rose-500 transition-colors" />
         <input 
           value={searchTerm} 
           onChange={e => setSearchTerm(e.target.value)} 
           placeholder="ابحث عن قرية في كافة المراكز..." 
           className="w-full bg-white rounded-[2rem] py-5 pr-14 pl-8 font-black text-sm outline-none shadow-sm border border-slate-100 focus:border-rose-300 transition-all" 
         />
      </div>

      {/* Districts Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
         {loading ? (
           <div className="col-span-full py-20 flex justify-center"><Loader2 className="h-12 w-12 animate-spin text-rose-500" /></div>
         ) : districts.sort((a,b)=>a.name.localeCompare(b.name)).map(dist => {
           const filteredVillages = dist.villages.filter(v => v.name.includes(searchTerm));
           if (searchTerm && filteredVillages.length === 0) return null;

           return (
             <div key={dist.id} className="bg-white p-8 rounded-[3.5rem] border border-slate-100 shadow-xl flex flex-col gap-6 group hover:border-rose-500 transition-all animate-reveal">
                <div className="flex items-center justify-between flex-row-reverse">
                   <div className="flex items-center gap-4 flex-row-reverse text-right">
                      <div className="bg-slate-50 p-4 rounded-2xl text-rose-500 group-hover:bg-rose-500 group-hover:text-white transition-all shadow-sm">
                         <Building2 className="h-6 w-6" />
                      </div>
                      <h4 className="font-black text-xl text-slate-900">{dist.name}</h4>
                   </div>
                   <span className="bg-rose-50 text-rose-600 px-4 py-1 rounded-full text-[10px] font-black">{dist.villages.length}</span>
                </div>

                <div className="space-y-2 overflow-y-auto max-h-64 no-scrollbar border-r-4 border-slate-50 pr-4">
                   {filteredVillages.sort((a,b)=>a.name.localeCompare(b.name)).map(v => (
                     <div key={v.id} className="flex items-center justify-between p-3 rounded-xl hover:bg-slate-50 transition-colors flex-row-reverse group/item">
                        <div className="flex items-center gap-3 flex-row-reverse">
                           <div className="w-1.5 h-1.5 rounded-full bg-rose-300"></div>
                           <p className="text-xs font-bold text-slate-600">{v.name}</p>
                        </div>
                        <button onClick={() => handleRemoveVillage(dist.id, v)} className="p-2 text-rose-200 hover:text-rose-500 opacity-0 group-hover/item:opacity-100 transition-all">
                           <Trash2 className="h-4 w-4" />
                        </button>
                     </div>
                   ))}
                </div>
             </div>
           );
         })}
      </div>
    </div>
  );
};

export default AdminGeographyManager;

