          </div>
          <div onClick={() => selectedDistrict ? setIsVillOpen(true) : alert('يرجى اختيار المركز أولاً')} className={`p-4 rounded-[1.8rem] flex items-center justify-between cursor-pointer border-2 border-transparent transition-all ${selectedDistrict ? 'bg-slate-50 active:border-emerald-500 hover:bg-white hover:shadow-md' : 'bg-slate-100 opacity-50'}`}>
             <ChevronDown className="h-4 w-4 text-slate-300" />
             <div className="text-right truncate flex-1 px-1">
                <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5 tracking-tighter">القرية/المنطقة</p>
                <p className="text-xs font-black text-slate-800 truncate">{selectedVillage?.name || 'اختر القرية'}</p>
