                <div className="grid grid-cols-2 gap-3 max-h-[50vh] overflow-y-auto no-scrollbar pb-6 px-2">
                   {displayDistricts.map(d => (
                     <button key={d.id} onClick={() => { onDistrictSelect(d); setIsDistOpen(false); }} className={`p-5 rounded-[1.8rem] font-black text-sm transition-all border-2 ${selectedDistrict?.id === d.id ? 'bg-emerald-600 text-white border-emerald-500 shadow-xl scale-105' : 'bg-slate-50 text-slate-600 border-transparent hover:border-emerald-200'}`}>{d.name}</button>
                   ))}
                </div>
             </div>
          </div>
       )}
       {isVillOpen && (
          <div className="fixed inset-0 z-[5000] bg-slate-950/80 backdrop-blur-md flex items-end md:items-center justify-center p-4 animate-in fade-in">
             <div className="bg-white w-full max-w-md rounded-t-[3rem] md:rounded-[3.5rem] p-6 flex flex-col h-[80vh] md:h-auto md:max-h-[85vh] shadow-2xl">
                <div className="flex justify-between items-center mb-8 px-2 shrink-0">
                   <button onClick={() => setIsVillOpen(false)} className="p-4 bg-slate-50 text-slate-400 rounded-2xl"><X /></button>
                   <div className="text-right"><h3 className="text-2xl font-black">قرى مركز {selectedDistrict?.name}</h3><p className="text-[10px] font-bold text-slate-400 uppercase">{selectedDistrict?.villages.length} قرية مسجلة</p></div>
                </div>
                <div className="px-2 mb-6 shrink-0">
                   <div className="relative">
                      <Search className="absolute right-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-300" />
                      <input value={villSearch} onChange={e => setVillSearch(e.target.value)} placeholder="بحث سريع عن اسم القرية أو العزبة..." className="w-full bg-slate-50 rounded-[1.5rem] p-5 pr-12 text-sm font-black outline-none border-2 border-slate-100 focus:border-emerald-500 text-right" />
                   </div>
                </div>
                <div className="flex-1 overflow-y-auto no-scrollbar space-y-2.5 px-2 pb-10">
                   {selectedDistrict?.villages.filter(v => v.name.includes(villSearch)).map(v => (
                     <button key={v.id} onClick={() => { onVillageSelect(v); setIsVillOpen(false); setVillSearch(''); }} className={`w-full p-6 rounded-[2rem] font-black text-md text-right flex items-center justify-between flex-row-reverse transition-all border-2 ${selectedVillage?.id === v.id ? 'bg-emerald-50 text-emerald-600 border-emerald-200 shadow-md' : 'bg-slate-50 text-slate-600 border-transparent hover:bg-white hover:border-emerald-100'}`}>
                        {v.name}
                        {selectedVillage?.id === v.id ? <Check className="h-6 w-6 text-emerald-500" /> : <ChevronLeft className="h-5 w-5 text-slate-200" />}
                     </button>
                   ))}
                </div>
             </div>
          </div>
       )}
    </div>
  );
};

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [geoData, setGeoData] = useState<District[]>([]);
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [ads, setAds] = useState<Ad[]>([]);

  // Order states
  const [pickupDist, setPickupDist] = useState<District | null>(null);
  const [pickupVill, setPickupVill] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffDist, setDropoffDist] = useState<District | null>(null);
  const [dropoffVill, setDropoffVill] = useState<Village | null>(null);
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [rideVehicle, setRideVehicle] = useState<VehicleType>('TOKTOK');
  const [aiRoadDistance, setAiRoadDistance] = useState<number | null>(null);
  const [isCalculatingAi, setIsCalculatingAi] = useState(false);
  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionImg, setPrescriptionImg] = useState<string | null>(null);

  // Active order states
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [viewingRest, setViewingRest] = useState<Restaurant | null>(null);

  useEffect(() => {
    const unsubGeo = onSnapshot(collection(db, "geo_config"), (snap) => {
      setGeoData(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[]);
    });
    const unsubRest = onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    const unsubAds = onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });
    const unsubOrders = onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.sort((a, b) => b.createdAt - a.createdAt).find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubGeo(); unsubRest(); unsubAds(); unsubOrders(); };
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder?.id, activeOrder?.status]);

  useEffect(() => {
    const fetchAiDist = async () => {
      if (!pickupVill || !dropoffVill) { setAiRoadDistance(null); return; }
      if (pickupVill.id === dropoffVill.id) { setAiRoadDistance(2); return; }
      setIsCalculatingAi(true);
      try {
        const straight = calculateDistance(pickupVill.center.lat, pickupVill.center.lng, dropoffVill.center.lat, dropoffVill.center.lng);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const resp = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `بناءً على خريطة محافظة المنوفية، قدر المسافة الحقيقية للسيارات بين قرية "${pickupVill.name}" و قرية "${dropoffVill.name}". المسافة الجوية هي ${straight.toFixed(1)} كم. أجب برقم المسافة فقط بالكيلومتر.`,
        });
        const distText = resp.text?.trim() || '0';
        const dist = parseFloat(distText);
        setAiRoadDistance(isNaN(dist) ? parseFloat((straight * 1.35).toFixed(1)) : dist);
      } catch { setAiRoadDistance(calculateDistance(pickupVill.center.lat, pickupVill.center.lng, dropoffVill.center.lat, dropoffVill.center.lng) * 1.3); }
      finally { setIsCalculatingAi(false); }
    };
    fetchAiDist();
  }, [pickupVill?.id, dropoffVill?.id]);

  const approxRidePrice = useMemo(() => {
    if (!pickupVill || !dropoffVill) return 0;
    const dist = aiRoadDistance || calculateDistance(pickupVill.center.lat, pickupVill.center.lng, dropoffVill.center.lat, dropoffVill.center.lng);
    const multi = (DEFAULT_PRICING.multipliers as any)[rideVehicle] || 1;
    if (pickupVill.id === dropoffVill.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multi), DEFAULT_PRICING.minPrice);
  }, [pickupVill, dropoffVill, rideVehicle, aiRoadDistance]);

  const handleCreateRideOrder = async () => {
    if(!pickupVill || !dropoffVill) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'TAXI',
        pickup: { address: pickupVill.name, lat: pickupVill.center.lat, lng: pickupVill.center.lng, villageName: pickupVill.name },
        dropoff: { address: dropoffVill.name, lat: dropoffVill.center.lat, lng: dropoffVill.center.lng, villageName: dropoffVill.name },
        pickupNotes, dropoffNotes, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), 
        requestedVehicleType: rideVehicle, price: approxRidePrice, distance: aiRoadDistance || 0,
        operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
    } catch { alert('خطأ في الاتصال'); } finally { setIsSubmitting(false); }
  };

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRest || !dropoffVill) return alert('يرجى تحديد مكان التوصيل أولاً');
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(viewingRest.lat, viewingRest.lng, dropoffVill.center.lat, dropoffVill.center.lng);
      const delivery = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodSum = cart.reduce((acc, c) => acc + (c.price * c.quantity), 0);
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRest.name, lat: viewingRest.lat, lng: viewingRest.lng, villageName: viewingRest.address },
        dropoff: { address: dropoffVill.name, lat: dropoffVill.center.lat, lng: dropoffVill.center.lng, villageName: dropoffVill.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: delivery + foodSum, distance: dist, foodItems: cart, restaurantId: viewingRest.id, restaurantName: viewingRest.name,
        pickupNotes: `طلب طعام من ${viewingRest.name}`, dropoffNotes, operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
      setViewingRest(null);
    } catch { alert('خطأ في إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  const handlePharmacyOrder = async () => {
    if(!dropoffVill) return alert('يرجى تحديد مكان التوصيل');
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'PHARMACY',
        dropoff: { address: dropoffVill.name, lat: dropoffVill.center.lat, lng: dropoffVill.center.lng, villageName: dropoffVill.name },
        dropoffNotes, notes: pharmacyNotes, prescriptionImage: prescriptionImg,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: 25, distance: 0, operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
      setPharmacyNotes(''); setPrescriptionImg(null);
    } catch { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-50">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRest && <RestaurantMenu restaurant={viewingRest} onClose={() => setViewingRest(null)} onCheckout={handleCheckoutFood} />}

      <div className="rh-ui-panel no-scrollbar z-[100] bg-slate-50 overflow-y-auto h-full">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-5 md:p-12 space-y-10 pb-40 max-w-2xl mx-auto text-right">
          {!activeOrder ? (
            <>
              {/* Header */}
              <div className="flex items-center justify-between">
                 <div className="text-right">
                    <h2 className="text-4xl font-black text-slate-950 tracking-tighter">وصـــلــهــا</h2>
                    <p className="text-slate-400 font-bold text-xs uppercase mt-1 tracking-widest">خدمة التوصيل الأذكى في المنوفية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-5 bg-emerald-50 text-emerald-600 rounded-[2.2rem] shadow-sm active:scale-90 transition-all border-none relative group">
                    <Bot className="h-8 w-8" />
                    <span className="absolute -top-1 -right-1 flex h-4 w-4"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span><span className="relative inline-flex rounded-full h-4 w-4 bg-emerald-500"></span></span>
                 </button>
              </div>

              {/* Ads Carousel */}
              {ads.length > 0 && (
                <div className="flex gap-5 overflow-x-auto no-scrollbar py-2 scroll-smooth">
                   {ads.filter(ad => ad.isActive).map(ad => (
                     <div key={ad.id} onClick={() => setViewingRest(restaurants.find(r => r.id === ad.targetId) || null)} className="min-w-[85%] aspect-video bg-slate-900 rounded-[3rem] overflow-hidden relative shadow-2xl active:scale-95 transition-all group cursor-pointer border-4 border-white/10">
                        <img src={ad.imageUrl} className="w-full h-full object-cover opacity-70 group-hover:scale-110 transition-transform duration-700" alt={ad.title} />
                        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent flex flex-col justify-end p-8">
                           <div className="bg-emerald-500 text-white px-4 py-1.5 rounded-full text-[10px] font-black w-fit mb-3 uppercase tracking-widest">{ad.type}</div>
                           <h4 className="text-white font-black text-2xl leading-tight mb-2">{ad.title}</h4>
                           <p className="text-white/60 text-xs font-bold line-clamp-1">{ad.description}</p>
                        </div>
                     </div>
                   ))}
                </div>
              )}

              {/* Service Categories */}
              <div className="grid grid-cols-3 gap-4">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-10 rounded-[3rem] flex flex-col items-center gap-4 border-4 transition-all duration-500 ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-[0_20px_50px_rgba(16,185,129,0.2)] scale-105' : 'bg-white border-transparent text-slate-300 opacity-60 hover:opacity-100 hover:border-slate-100'}`}>
                       {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as any, { className: "h-10 w-10" }) : cat.icon}
                       <span className="text-xs font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {/* Order Logic per Category */}
              {selectedCategory === 'TAXI' && (
                <div className="space-y-8 animate-reveal">
                   <LocationSelector districts={geoData} label="نقطة الانطلاق" helper="موقع استلامك الحالي" icon={<MapPin />} iconBg="bg-emerald-500" selectedDistrict={pickupDist} selectedVillage={pickupVill} notes={pickupNotes} onDistrictSelect={setPickupDist} onVillageSelect={setPickupVill} onNotesChange={setPickupNotes} />
                   <LocationSelector districts={geoData} label="وجهة الوصول" helper="إلى أين نذهب بك؟" icon={<Check />} iconBg="bg-rose-500" selectedDistrict={dropoffDist} selectedVillage={dropoffVill} notes={dropoffNotes} onDistrictSelect={setDropoffDist} onVillageSelect={setDropoffVill} onNotesChange={setDropoffNotes} />

                   <div className="grid grid-cols-3 gap-3">
                      {[
                        { id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-4 w-4" /> },
                        { id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-4 w-4" /> },
                        { id: 'CAR', label: 'سيارة', icon: <Car className="h-4 w-4" /> }
                      ].map(v => (
                        <button key={v.id} onClick={() => setRideVehicle(v.id as any)} className={`py-5 rounded-[2rem] font-black text-xs border-2 transition-all flex items-center justify-center gap-2 ${rideVehicle === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-xl' : 'bg-white border-slate-100 text-slate-300'}`}>
                           {v.icon} {v.label}
                        </button>
                      ))}
                   </div>

                   <div className="bg-slate-950 p-10 rounded-[4rem] text-white space-y-10 relative overflow-hidden">
                      <div className="absolute top-0 left-0 w-full h-full bg-emerald-500/5 blur-3xl"></div>
                      <div className="text-center space-y-2 relative z-10">
                        <p className="text-[10px] font-black text-emerald-400 uppercase tracking-[0.4em]">التكلفة التقريبية للرحلة</p>
                        <h3 className="text-6xl font-black">{isCalculatingAi ? <Loader2 className="animate-spin inline-block h-10 w-10 text-emerald-500" /> : approxRidePrice} <span className="text-sm opacity-40 uppercase">ج.م</span></h3>
                      </div>
                      <button onClick={handleCreateRideOrder} disabled={isSubmitting || !pickupVill || !dropoffVill} className="w-full bg-emerald-600 text-white py-8 rounded-[2.8rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 hover:bg-emerald-500 animate-glow">
                         {isSubmitting ? <Loader2 className="animate-spin" /> : <>تأكيد طلب المشوار <ArrowLeft /></>}
                      </button>
                   </div>
                </div>
              )}

              {selectedCategory === 'FOOD' && (
                <div className="space-y-8 animate-reveal">
                   <LocationSelector districts={geoData} label="مكان التوصيل" helper="أين ستستلم وجبتك؟" icon={<MapPin />} iconBg="bg-rose-500" selectedDistrict={dropoffDist} selectedVillage={dropoffVill} notes={dropoffNotes} onDistrictSelect={setDropoffDist} onVillageSelect={setDropoffVill} onNotesChange={setDropoffNotes} />
                   <div className="space-y-4">
                      <div className="flex justify-between items-center px-4">
                         <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">مطاعم المنوفية المتاحة</h4>
                         <Store className="h-4 w-4 text-slate-300" />
                      </div>
                      <div className="grid grid-cols-1 gap-4">
                        {restaurants.map(rest => (
                          <div key={rest.id} onClick={() => setViewingRest(rest)} className="bg-white p-6 rounded-[3.5rem] border-2 border-transparent hover:border-emerald-500 shadow-xl shadow-slate-100/50 flex flex-row-reverse justify-between items-center transition-all cursor-pointer group">
                             <div className="flex items-center gap-5 flex-row-reverse text-right">
                                <div className="w-20 h-20 bg-slate-900 rounded-[2.2rem] overflow-hidden shadow-2xl group-hover:scale-105 transition-transform">
                                   {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" alt="" /> : <UtensilsCrossed className="p-6 text-emerald-400" />}
                                </div>
                                <div>
                                   <h4 className="font-black text-xl text-slate-900 group-hover:text-emerald-600 transition-colors">{rest.name}</h4>
                                   <p className="text-[10px] font-bold text-slate-400 mt-1">{rest.category} • خدمة فورية</p>
                                </div>
                             </div>
                             <div className="bg-slate-50 p-4 rounded-2xl text-slate-300 group-hover:bg-emerald-500 group-hover:text-white transition-all shadow-sm">
                                <ChevronLeft className="h-6 w-6" />
                             </div>
                          </div>
                        ))}
                      </div>
                   </div>
                </div>
              )}

              {selectedCategory === 'PHARMACY' && (
                <div className="space-y-8 animate-reveal">
                   <LocationSelector districts={geoData} label="مكان التوصيل" helper="عنوانك لاستلام العلاج" icon={<MapPin />} iconBg="bg-rose-500" selectedDistrict={dropoffDist} selectedVillage={dropoffVill} notes={dropoffNotes} onDistrictSelect={setDropoffDist} onVillageSelect={setDropoffVill} onNotesChange={setDropoffNotes} />
                   <div className="bg-white p-10 rounded-[4rem] shadow-2xl border border-slate-100 space-y-8">
                      <div className="text-center space-y-3">
                         <div className="bg-sky-50 w-20 h-20 rounded-[2.5rem] flex items-center justify-center mx-auto text-sky-500 shadow-inner">
                            <Pill className="h-10 w-10" />
                         </div>
                         <h4 className="text-xl font-black text-slate-800">طلب أدوية من الصيدلية</h4>
                         <p className="text-[10px] font-bold text-slate-400">سنقوم بجلب طلبك من أقرب صيدلية لعنوانك</p>
