          ) : (
            <div className="space-y-12 animate-in fade-in py-10">
               {/* State: Searching for Driver */}
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="text-center space-y-12">
                    <div className="relative inline-block">
                       <div className="bg-white p-14 rounded-full shadow-2xl relative z-10 animate-glow border-8 border-emerald-50">
