                             <span className="text-emerald-600 font-black text-xs uppercase tracking-widest">كابتن معتمد - وصلها المنوفية</span>
                          </div>
                       </div>
                    </div>
                    <div className="grid grid-cols-2 gap-5">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-5 shadow-2xl active:scale-95 transition-all hover:bg-slate-900"><PhoneCall className="h-8 w-8" /> اتصال هاتف</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-8 rounded-[2.8rem] font-black text-xl flex items-center justify-center gap-5 active:scale-95 transition-all relative">
                          <MessageCircle className="h-8 w-8 text-emerald-500" /> دردشة مباشرة
                          <span className="absolute top-6 right-8 h-4 w-4 bg-emerald-500 rounded-full border-2 border-white animate-pulse"></span>
                       </button>
                    </div>
                    <div className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 flex items-center gap-4 flex-row-reverse text-right">
                       <Info className="text-slate-300 shrink-0" />
                       <p className="text-[10px] font-bold text-slate-400">يرجى التأكد من استلام كود التوصيل من الكابتن فور الوصول لضمان توثيق الرحلة.</p>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      {/* Modern Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-3xl border-t border-slate-100 px-10 py-8 flex justify-around items-center z-[150] shadow-[0_-25px_50px_rgba(0,0,0,0.08)] flex-row-reverse rounded-t-[3.5rem]">
         {[
           {id: 'NEW', icon: <Plus className="h-8 w-8" />, label: 'طلب جديد'},
           {id: 'ACTIVITY', icon: <History className="h-8 w-8" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-8 w-8" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all duration-500 border-none bg-transparent ${activeView === tab.id ? 'text-emerald-600 scale-110 translate-y-[-10px]' : 'text-slate-300 opacity-60 hover:opacity-100'}`}>
              <div className={`p-4 rounded-3xl transition-all ${activeView === tab.id ? 'bg-emerald-50 shadow-2xl shadow-emerald-200' : ''}`}>{tab.icon}</div>
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

