@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --brand-emerald: #10b981;
  --brand-emerald-deep: #064e3b;
  --brand-gold: #fbbf24;
  --slate-950: #020617;
  --slate-900: #0f172a;
  --bg-main: #f8fafc;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: var(--bg-main);
  color: var(--slate-900);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* Animations */
@keyframes glow-emerald {
  0% { box-shadow: 0 0 5px rgba(16, 185, 129, 0.2); }
  50% { box-shadow: 0 0 20px rgba(16, 185, 129, 0.4); }
  100% { box-shadow: 0 0 5px rgba(16, 185, 129, 0.2); }
}

.animate-glow-emerald {
  animation: glow-emerald 2s infinite ease-in-out;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-5px); }
}

.animate-float {
  animation: float 3s infinite ease-in-out;
}

/* UI Panel - Enhanced Aesthetics */
.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(20px);
  border-top-left-radius: 3rem;
  border-top-right-radius: 3rem;
  box-shadow: 0 -20px 60px -15px rgba(0, 0, 0, 0.1);
  max-height: 90vh;
  overflow-y: auto;
  padding-bottom: calc(6rem + env(safe-area-inset-bottom));
  border-top: 1px solid rgba(255, 255, 255, 0.5);
}

/* Custom Scrollbar */
.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

/* Gradient Text */
.text-gradient-emerald {
