const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showFullMenu, setShowFullMenu] = useState(false);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-slate-50 z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       {showFullMenu && restaurant.menuImageURL && <HighResMenuViewer url={restaurant.menuImageURL} onClose={() => setShowFullMenu(false)} />}

       <div className="bg-gradient-to-br from-slate-900 to-slate-950 p-8 pt-14 text-white flex justify-between items-center shadow-2xl relative overflow-hidden shrink-0">
          <div className="absolute top-0 right-0 w-full h-full opacity-10 pointer-events-none">
             {restaurant.photoURL && <img src={restaurant.photoURL} className="w-full h-full object-cover blur-2xl" alt="" />}
          </div>
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl relative z-10 hover:bg-white/20 active:scale-90 transition-all shadow-xl"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right relative z-10">
             <h3 className="text-3xl font-black tracking-tight">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400 uppercase tracking-widest mt-1">{restaurant.category} • المنوفية</p>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar">
          {restaurant.menuImageURL && (
            <button onClick={() => setShowFullMenu(true)} className="w-full bg-gradient-to-r from-emerald-600 to-emerald-700 p-8 rounded-[3rem] text-white flex justify-between items-center shadow-xl hover:scale-[1.01] transition-all active:scale-95 border-none group">
               <div className="bg-white/20 p-4 rounded-2xl group-hover:rotate-12 transition-transform"><ZoomIn className="h-7 w-7" /></div>
               <div className="text-right">
                  <h4 className="font-black text-xl">تصفح المنيو المصور</h4>
                  <p className="text-[10px] font-bold opacity-80 uppercase tracking-[0.2em] mt-1">اضغط للتكبير وحفظ الصور</p>
               </div>
            </button>
          )}

          <div className="space-y-4 pb-20">
             <h5 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] text-right px-4 mb-2">الوجبات والأصناف</h5>
             {restaurant.menu?.length > 0 ? restaurant.menu.map(item => (
               <div key={item.id} className="bg-white p-6 rounded-[2.8rem] shadow-sm border border-slate-100 flex justify-between items-center group hover:border-emerald-200 transition-all">
                  <div className="flex items-center gap-6">
                     <div className="flex items-center gap-2 bg-slate-50 p-2.5 rounded-2xl border border-slate-100">
                        <button onClick={() => addToCart(item)} className="p-2.5 bg-emerald-500 text-white rounded-xl active:scale-75 transition-all shadow-lg hover:bg-emerald-600"><Plus className="h-4 w-4" /></button>
                        <span className="font-black text-xl w-8 text-center text-slate-800">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                        <button onClick={() => removeFromCart(item.id)} className="p-2.5 bg-rose-50 text-rose-500 rounded-xl active:scale-75 transition-all hover:bg-rose-100"><Minus className="h-4 w-4" /></button>
                     </div>
                     <div className="text-left"><p className="font-black text-2xl text-emerald-600 leading-none">{item.price} <span className="text-[10px] text-slate-400">ج.م</span></p></div>
                  </div>
                  <div className="text-right flex items-center gap-5 flex-row-reverse">
                     <div className="w-20 h-20 bg-slate-100 rounded-[1.8rem] overflow-hidden border border-slate-50 shrink-0 shadow-inner">
                        {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} /> : <UtensilsCrossed className="p-6 text-slate-200" />}
                     </div>
                     <div className="max-w-[150px]">
                       <p className="font-black text-slate-900 text-xl leading-tight">{item.name}</p>
                       <p className="text-[11px] font-bold text-slate-400 mt-2 line-clamp-2 leading-relaxed">{item.description || 'وجبة طازجة محضرة بأفضل المكونات المنوفية.'}</p>
                     </div>
                  </div>
               </div>
             )) : (
               <div className="text-center py-24 bg-white rounded-[4rem] text-slate-300 font-bold border-4 border-dashed border-slate-100">بانتظار تحديث قائمة الطعام...</div>
             )}
          </div>
       </div>

       {cart.length > 0 && (
         <div className="p-8 bg-white/80 backdrop-blur-3xl border-t border-slate-100 animate-in slide-in-from-bottom pb-12 shadow-[0_-20px_50px_rgba(0,0,0,0.05)] shrink-0">
            <div className="flex justify-between items-center mb-8 px-4">
               <div className="text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">إجمالي الحساب</p>
                  <p className="text-3xl font-black text-slate-950">{total} <span className="text-sm opacity-40">ج.م</span></p>
               </div>
               <div className="bg-emerald-50 px-6 py-2 rounded-2xl border border-emerald-100 flex items-center gap-2">
                  <ShoppingBag className="h-4 w-4 text-emerald-600" />
                  <span className="font-black text-emerald-600 text-xs">{cart.length} أصناف</span>
               </div>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-slate-950 text-white py-8 rounded-[2.8rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all hover:bg-slate-900 animate-glow-emerald">
               تأكيد طلب الوجبات <ArrowLeft className="h-6 w-6" />
            </button>
         </div>
       )}
    </div>
  );
};

