const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [geoData, setGeoData] = useState<District[]>([]);
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [ads, setAds] = useState<Ad[]>([]);

  const [pickupDist, setPickupDist] = useState<District | null>(null);
  const [pickupVill, setPickupVill] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffDist, setDropoffDist] = useState<District | null>(null);
  const [dropoffVill, setDropoffVill] = useState<Village | null>(null);
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [rideVehicle, setRideVehicle] = useState<VehicleType>('TOKTOK');

  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');
  const [viewingRest, setViewingRest] = useState<Restaurant | null>(null);

  useEffect(() => {
    const unsubGeo = onSnapshot(collection(db, "geo_config"), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[];
      setGeoData(data.length > 0 ? data : STATIC_GEO);
    });
    const unsubRest = onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    const unsubAds = onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });
    const unsubOrders = onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.sort((a, b) => b.createdAt - a.createdAt).find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubGeo(); unsubRest(); unsubAds(); unsubOrders(); };
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id), orderBy("createdAt", "desc")), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder?.id, activeOrder?.status]);

  const approxRidePrice = useMemo(() => {
    if (!pickupVill || !dropoffVill) return 0;
    const dist = calculateDistance(pickupVill.center.lat, pickupVill.center.lng, dropoffVill.center.lat, dropoffVill.center.lng);
    const multi = (DEFAULT_PRICING.multipliers as any)[rideVehicle] || 1;
    if (pickupVill.id === dropoffVill.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multi), DEFAULT_PRICING.minPrice);
  }, [pickupVill, dropoffVill, rideVehicle]);

  const handleCreateRideOrder = async () => {
    if(!pickupVill || !dropoffVill) return;
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'TAXI',
        pickup: { address: pickupVill.name, lat: pickupVill.center.lat, lng: pickupVill.center.lng, villageName: pickupVill.name },
        dropoff: { address: dropoffVill.name, lat: dropoffVill.center.lat, lng: dropoffVill.center.lng, villageName: dropoffVill.name },
        pickupNotes, dropoffNotes, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), 
        requestedVehicleType: rideVehicle, price: approxRidePrice, distance: 0,
        operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
    } catch { alert('خطأ في الاتصال'); } finally { setIsSubmitting(false); }
  };

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRest || !dropoffVill) return alert('يرجى تحديد مكان التوصيل أولاً');
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(viewingRest.lat, viewingRest.lng, dropoffVill.center.lat, dropoffVill.center.lng);
      const delivery = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodSum = cart.reduce((acc, c) => acc + (c.price * c.quantity), 0);
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRest.name, lat: viewingRest.lat, lng: viewingRest.lng, villageName: viewingRest.address },
        dropoff: { address: dropoffVill.name, lat: dropoffVill.center.lat, lng: dropoffVill.center.lng, villageName: dropoffVill.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: delivery + foodSum, distance: dist, foodItems: cart, restaurantId: viewingRest.id, restaurantName: viewingRest.name,
        pickupNotes: `طلب طعام من ${viewingRest.name}`, dropoffNotes, operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
      });
      setViewingRest(null);
    } catch { alert('خطأ في إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-100">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRest && <RestaurantMenu restaurant={viewingRest} onClose={() => setViewingRest(null)} onCheckout={handleCheckoutFood} />}

      <div className="rh-ui-panel no-scrollbar z-[100] bg-slate-50/95 shadow-inner">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-6 md:p-12 space-y-10 pb-40 max-w-2xl mx-auto text-right h-full overflow-y-auto no-scrollbar">
          {!activeOrder ? (
            <>
              {/* Premium Header */}
              <div className="flex items-center justify-between">
                 <div className="text-right">
