const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showFullMenu, setShowFullMenu] = useState(false);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       {showFullMenu && restaurant.menuImageURL && <HighResMenuViewer url={restaurant.menuImageURL} onClose={() => setShowFullMenu(false)} />}

       <div className="bg-slate-900 p-8 pt-14 text-white flex justify-between items-center shadow-xl relative overflow-hidden shrink-0">
          <div className="absolute top-0 right-0 w-full h-full opacity-10 pointer-events-none">
             {restaurant.photoURL && <img src={restaurant.photoURL} className="w-full h-full object-cover blur-2xl" alt="" />}
          </div>
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl relative z-10 hover:bg-white/20 active:scale-90 transition-all"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right relative z-10">
             <h3 className="text-2xl font-black">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400 uppercase mt-1">{restaurant.category} • المنوفية</p>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar bg-slate-50">
          {restaurant.menuImageURL && (
            <button onClick={() => setShowFullMenu(true)} className="w-full bg-emerald-600 p-6 rounded-[2.5rem] text-white flex justify-between items-center shadow-xl cursor-pointer hover:scale-[1.01] transition-transform active:scale-95 border-none group">
               <div className="bg-white/20 p-4 rounded-2xl group-hover:rotate-12 transition-transform"><ZoomIn className="h-6 w-6" /></div>
               <div className="text-right">
                  <h4 className="font-black text-lg">عرض المنيو الكامل</h4>
                  <p className="text-[10px] font-bold opacity-80 uppercase tracking-widest mt-1">اضغط للتكبير وحفظ الصور</p>
               </div>
            </button>
          )}

          <div className="space-y-4">
             <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-right px-2 mb-2">أصناف الطعام المتاحة</h5>
             {restaurant.menu?.length > 0 ? restaurant.menu.map(item => (
               <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center group hover:border-emerald-100 transition-all">
                  <div className="flex items-center gap-4">
                     <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl border border-slate-100">
                        <button onClick={() => addToCart(item)} className="p-2 bg-emerald-500 text-white rounded-xl active:scale-75 transition-all shadow-lg"><Plus className="h-4 w-4" /></button>
                        <span className="font-black text-lg w-6 text-center text-slate-800">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                        <button onClick={() => removeFromCart(item.id)} className="p-2 bg-rose-50 text-rose-500 rounded-xl active:scale-75 transition-all"><Minus className="h-4 w-4" /></button>
                     </div>
                     <div className="text-left"><p className="font-black text-emerald-600">{item.price} ج.م</p></div>
                  </div>
                  <div className="text-right flex items-center gap-4 flex-row-reverse">
                     <div className="w-16 h-16 bg-slate-100 rounded-2xl overflow-hidden border border-slate-50 shrink-0">
                        {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} /> : <UtensilsCrossed className="p-4 text-slate-200" />}
                     </div>
                     <div className="max-w-[150px]">
                       <p className="font-black text-slate-800 text-md leading-tight">{item.name}</p>
                       <p className="text-[10px] font-bold text-slate-400 mt-1 line-clamp-2">{item.description || 'وجبة طازجة محضرة بأفضل المكونات'}</p>
                     </div>
                  </div>
               </div>
             )) : (
               <div className="text-center py-20 bg-white rounded-[3rem] text-slate-300 font-bold border-4 border-dashed border-slate-100">بانتظار تحديث قائمة الطعام...</div>
             )}
          </div>
       </div>

       {cart.length > 0 && (
         <div className="p-8 bg-white border-t border-slate-100 animate-in slide-in-from-bottom pb-12 shadow-2xl shrink-0">
            <div className="flex justify-between items-center mb-6 px-4">
               <p className="text-2xl font-black text-slate-900">{total} <span className="text-xs opacity-40 uppercase">ج.م</span></p>
               <p className="text-xs font-black text-slate-400 uppercase tracking-widest">إجمالي الطلب</p>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-7 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
               تأكيد وطلب الطعام الآن
            </button>
         </div>
       )}
    </div>
  );
};

