            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-slate-950 text-white py-8 rounded-[3rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all hover:bg-slate-900 animate-glow-emerald border-none">
