const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [ads, setAds] = useState<Ad[]>([]);
  const [geoData, setGeoData] = useState<District[]>([]);

  const [pickupDistrict, setPickupDistrict] = useState<District | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffDistrict, setDropoffDistrict] = useState<District | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [dropoffNotes, setDropoffNotes] = useState('');

  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [expandedAd, setExpandedAd] = useState<Ad | null>(null);
  const [rideVehicleType, setRideVehicleType] = useState<VehicleType>('TOKTOK');
  const [aiRoadDistance, setAiRoadDistance] = useState<number | null>(null);
  const [isCalculatingAiDist, setIsCalculatingAiDist] = useState(false);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [rating, setRating] = useState(5);
  const [feedback, setFeedback] = useState('');

  useEffect(() => {
    // جلب بيانات الجغرافيا الديناميكية من Firestore
    const unsubGeo = onSnapshot(collection(db, "geo_config"), (snap) => {
      if (!snap.empty) {
        setGeoData(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as District[]);
      }
    });

    onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });

    onSnapshot(collection(db, "ads"), (snap) => {
      setAds(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Ad[]);
    });

    const q = query(collection(db, "orders"), where("customerId", "==", user.id));
    return onSnapshot(q, (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.sort((a, b) => b.createdAt - a.createdAt).find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  // AI Distance Calculation Logic
  useEffect(() => {
    const fetchAiDistance = async () => {
      if (!pickupVillage || !dropoffVillage) { setAiRoadDistance(null); return; }
      if (pickupVillage.id === dropoffVillage.id) { setAiRoadDistance(2); return; }
      setIsCalculatingAiDist(true);
      try {
        const straightDist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `قدر المسافة الحقيقية للسيارات بين قرية "${pickupVillage.name}" و قرية "${dropoffVillage.name}" في محافظة المنوفية. المسافة الجوية هي ${straightDist.toFixed(1)} كم. أجب برقم المسافة فقط.`,
        });
        const dist = parseFloat(response.text?.trim() || '0');
        setAiRoadDistance(isNaN(dist) ? parseFloat((straightDist * 1.4).toFixed(1)) : dist);
      } catch (error) {
        setAiRoadDistance(calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng) * 1.4);
      } finally { setIsCalculatingAiDist(false); }
    };
    fetchAiDistance();
  }, [pickupVillage?.id, dropoffVillage?.id]);

  const approxRidePrice = useMemo(() => {
    if (!pickupVillage || !dropoffVillage) return 0;
    const dist = aiRoadDistance || calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
    const multiplier = (DEFAULT_PRICING.multipliers as any)[rideVehicleType] || 1;
    if (pickupVillage.id === dropoffVillage.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multiplier), DEFAULT_PRICING.minPrice);
  }, [pickupVillage, dropoffVillage, rideVehicleType, aiRoadDistance]);

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى تحديد مكان التوصيل أولاً');
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

      const orderData: Partial<Order> = {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: deliveryPrice + foodTotal, distance: dist, operatorId: 'main', zoneId: 'monofia',
        paymentMethod: 'CASH', foodItems: cart, restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name,
        pickupNotes: `طلب طعام من مطعم ${viewingRestaurant.name}`, dropoffNotes
      };
      await addDoc(collection(db, "orders"), orderData);
      setViewingRestaurant(null);
    } catch (e) { alert('خطأ فني في إرسال طلب الطعام'); } finally { setIsSubmitting(false); }
  };

  const handleCreateRideOrder = async () => {
    if(!pickupVillage || !dropoffVillage) return;
    setIsSubmitting(true);
    try {
       await addDoc(collection(db, "orders"), {
          customerId: user.id, customerPhone: user.phone, category: 'TAXI',
          pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
          dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
          pickupNotes, dropoffNotes, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), 
          requestedVehicleType: rideVehicleType, price: approxRidePrice, distance: aiRoadDistance || 0,
          operatorId: 'main', zoneId: 'monofia', paymentMethod: 'CASH'
       });
    } catch(e) { alert('خطأ في إرسال طلب المشوار'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        status: OrderStatus.ACCEPTED, acceptedAt: Date.now(), price: offer.price
      });
    } catch (e) { alert('فشل قبول عرض الكابتن'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-slate-100">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}
      {expandedAd && <AdDetailModal ad={expandedAd} onClose={() => setExpandedAd(null)} onAction={(ad) => {
         if (ad.type === 'restaurant' && ad.targetId) {
            const rest = restaurants.find(r => r.id === ad.targetId);
            if (rest) setViewingRestaurant(rest);
         } else { window.open(`https://wa.me/${ADMIN_WHATSAPP}?text=${encodeURIComponent('أريد طلب العرض: ' + ad.title)}`); }
      }} />}

      <div className="rh-ui-panel no-scrollbar z-[100] bg-slate-50/95 shadow-inner">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-6 md:p-12 space-y-10 pb-40 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              {/* Premium Header */}
              <div className="flex items-center justify-between">
                 <div className="text-right">
                    <h2 className="text-4xl font-black text-slate-950 tracking-tighter flex items-center gap-3">
                       وصـــلــهــا
                       <div className="bg-emerald-500 w-2.5 h-2.5 rounded-full animate-pulse"></div>
                    </h2>
                    <p className="text-slate-400 font-bold text-[10px] uppercase mt-1 tracking-[0.3em]">المنوفية • خدمة توصيل ملكية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-5 bg-white text-emerald-600 rounded-[2rem] shadow-xl shadow-emerald-500/10 active:scale-90 transition-all border border-emerald-50 relative group overflow-hidden border-none">
                    <Bot className="h-8 w-8 relative z-10" />
                    <div className="absolute inset-0 bg-emerald-50 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                 </button>
              </div>

              {/* Enhanced Ads Carousel */}
              {ads.length > 0 && (
                <div className="flex gap-6 overflow-x-auto no-scrollbar py-2 scroll-smooth">
                   {ads.filter(ad => ad.isActive).map(ad => (
                     <div key={ad.id} onClick={() => setExpandedAd(ad)} className="min-w-[90%] aspect-video bg-slate-900 rounded-[3.5rem] overflow-hidden relative shadow-2xl active:scale-95 transition-all group cursor-pointer border-8 border-white">
                        <img src={ad.imageUrl} className="w-full h-full object-cover opacity-80 group-hover:scale-110 transition-transform duration-[1.5s]" alt={ad.title} />
                        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 flex flex-col justify-end p-8">
                           <div className="bg-emerald-500 text-white px-5 py-2 rounded-full text-[10px] font-black w-fit mb-3 uppercase tracking-widest shadow-lg">{ad.type}</div>
                           <h4 className="text-white font-black text-2xl md:text-3xl leading-tight mb-2 group-hover:translate-x-[-5px] transition-transform">{ad.title}</h4>
                        </div>
                     </div>
                   ))}
                </div>
              )}

              {/* Modern Service Selectors */}
              <div className="grid grid-cols-3 gap-5">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-10 md:py-12 rounded-[3.5rem] flex flex-col items-center gap-5 border-4 transition-all duration-700 ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-white border-transparent text-slate-300 opacity-50 hover:opacity-100 hover:border-slate-100'}`}>
                       <div className={`p-4 rounded-[1.5rem] ${selectedCategory === cat.id ? 'bg-emerald-50 shadow-inner' : 'bg-slate-50'}`}>
                          {React.isValidElement(cat.icon) ? React.cloneElement(cat.icon as React.ReactElement<any>, { className: "h-10 w-10" }) : cat.icon}
                       </div>
                       <span className="text-[11px] font-black uppercase tracking-[0.2em]">{cat.label}</span>
                    </button>
