       </div>

       {cart.length > 0 && (
         <div className="p-8 bg-white/80 backdrop-blur-3xl border-t border-slate-100 animate-in slide-in-from-bottom pb-12 shadow-[0_-20px_60px_rgba(0,0,0,0.05)] shrink-0">
            <div className="flex justify-between items-center mb-8 px-4">
               <div className="text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">إجمالي الفاتورة</p>
                  <p className="text-3xl font-black text-slate-950">{total} <span className="text-sm opacity-40">ج.م</span></p>
               </div>
               <div className="bg-emerald-50 px-6 py-2.5 rounded-2xl border border-emerald-100 flex items-center gap-2">
                  <ShoppingCart className="h-4 w-4 text-emerald-600" />
                  <span className="font-black text-emerald-600 text-xs">{cart.reduce((a,c) => a + c.quantity, 0)} قطع</span>
               </div>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-slate-950 text-white py-8 rounded-[3rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all hover:bg-slate-900 animate-glow-emerald border-none">
               إتمام الطلب وتحديد التوصيل <ArrowLeft className="h-6 w-6" />
            </button>
         </div>
       )}
    </div>
  );
};

